/**
   Checkout file storage (fsl_ckout_fs): the fsl__cfs_xxx() file
   operations of the checkout code. Each does what the fs.c function
   it is named after does, through the context's storage, which is
   fsl_ckout_fs_os (the fs.c functions themselves) unless another one
   is installed. The derived operations (creating a file's
   directories, copying, crawling a directory, symlinks as files) are
   written once here, in terms of the storage's members, so every
   storage gets the same behaviour.
*/
#include <string.h> /* memcpy() */
#include <stddef.h> /* offsetof() */
#include <time.h>   /* time() */
#include <errno.h>  /* ENOTDIR */

const fsl_ckout_fs fsl_ckout_fs_empty = fsl_ckout_fs_empty_m;

/* fsl_ckout_fs_os's members: the fs.c functions. */
static int fsl__cfs_os_stat(void * state, char const * zName,
                            fsl_fstat * tgt, bool derefLinks){
  (void)state;
  return fsl_stat(zName, tgt, derefLinks);
}
static int fsl__cfs_os_read(void * state, char const * zName, fsl_b * tgt){
  (void)state;
  return fsl_b_fill_from_filename(tgt, zName);
}
static int fsl__cfs_os_write(void * state, char const * zName,
                             void const * src, fsl_size_t n){
  fsl_b b = fsl_b_empty;
  (void)state;
  b.mem = (unsigned char *)src;
  b.capacity = b.used = n;
  return fsl_b_to_filename(&b, zName);
}
static int fsl__cfs_os_unlink(void * state, char const * zName){
  (void)state;
  return fsl_file_unlink(zName);
}
static int fsl__cfs_os_rename(void * state, char const * zFrom,
                              char const * zTo){
  (void)state;
  return fsl_file_rename(zFrom, zTo);
}
static int fsl__cfs_os_mkdir(void * state, char const * zName){
  (void)state;
  return fsl_mkdir(zName, false);
}
static int fsl__cfs_os_rmdir(void * state, char const * zName){
  (void)state;
  return fsl_rmdir(zName);
}
static int fsl__cfs_os_dirlist(void * state, char const * zDir,
                               fsl_ckout_fs_dir_f cb, void * cbState){
  (void)state;
  return fsl__dir_list(zDir, cb, cbState);
}
static int fsl__cfs_os_exec_set(void * state, char const * zName,
                                bool isExec){
  (void)state;
  return fsl_file_exec_set(zName, isExec);
}
static int fsl__cfs_os_mtime_set(void * state, char const * zName,
                                 fsl_time_t mtime){
  (void)state;
  return fsl_file_mtime_set(zName, mtime);
}
static int fsl__cfs_os_symlink_read(void * state, char const * zName,
                                    fsl_b * tgt){
  (void)state;
  return fsl_symlink_read(tgt, zName);
}
static int fsl__cfs_os_symlink_create(void * state, char const * zTarget,
                                      char const * zName){
  (void)state;
  return fsl_symlink_create(zTarget, zName, true);
}
static int fsl__cfs_os_copy(void * state, char const * zFrom,
                            char const * zTo){
  (void)state;
  return fsl_file_copy(zFrom, zTo);
}
static int fsl__cfs_os_hash(void * state, char const * zName, bool sha3,
                            fsl_b * tgt){
  (void)state;
  return sha3
    ? fsl_sha3sum_filename(zName, tgt)
    : fsl_sha1sum_filename(zName, tgt);
}

/* xWriteBlob is NULL: the library reads the blob and calls xWrite,
   as it always did. */
const fsl_ckout_fs fsl_ckout_fs_os = {
  FSL_CKOUT_FS_VERSION,
  fsl__cfs_os_stat, fsl__cfs_os_read, fsl__cfs_os_write,
  fsl__cfs_os_unlink, fsl__cfs_os_rename, fsl__cfs_os_mkdir,
  fsl__cfs_os_rmdir, fsl__cfs_os_dirlist, fsl__cfs_os_exec_set,
  fsl__cfs_os_mtime_set, fsl__cfs_os_symlink_read,
  fsl__cfs_os_symlink_create, fsl__cfs_os_copy, fsl__cfs_os_hash, NULL,
  NULL
};

/** Returns f's storage: the installed one, else fsl_ckout_fs_os. */
static fsl_ckout_fs const * fsl__cfs_get(fsl_cx const * const f){
  return f->ckoutFs.iVersion ? &f->ckoutFs : &fsl_ckout_fs_os;
}
#define CFS(F) fsl__cfs_get(F)

int fsl_cx_ckout_fs(fsl_cx * const f, fsl_ckout_fs const * pNew,
                    fsl_ckout_fs * pPrev){
  if( pNew && ((1!=pNew->iVersion && 2!=pNew->iVersion)
               || !pNew->xStat || !pNew->xRead || !pNew->xWrite
               || !pNew->xUnlink || !pNew->xRename || !pNew->xMkdir
               || !pNew->xRmdir || !pNew->xDirList
               || !pNew->xSymlinkRead != !pNew->xSymlinkCreate) ){
    return FSL_RC_MISUSE;
  }
  if( fsl_cx_txn_level(f) ) return FSL_RC_MISUSE;
  if( pPrev ) fsl_cx_ckout_fs_get(f, pPrev);
  f->ckoutFs = fsl_ckout_fs_empty;
  if( pNew ){
    /* A version 1 struct ends before xWriteBlob: copy no more. */
    memcpy(&f->ckoutFs, pNew, 1==pNew->iVersion
           ? offsetof(fsl_ckout_fs, xWriteBlob) : sizeof(fsl_ckout_fs));
  }
  return 0;
}

void fsl_cx_ckout_fs_get(fsl_cx const * const f, fsl_ckout_fs * dest){
  fsl_ckout_fs const * const s = f->ckoutFs.iVersion
    ? &f->ckoutFs : &fsl_ckout_fs_os;
  if( dest->iVersion>=2 ){
    *dest = *s;
  }else{
    /* The caller's struct may end before xWriteBlob: fill only the
       version 1 members, and say so. */
    memcpy(dest, s, offsetof(fsl_ckout_fs, xWriteBlob));
    dest->iVersion = 1;
  }
}

int fsl__cfs_stat(fsl_cx * const f, char const *zName, fsl_fstat * fst,
                  bool derefLinks){
  fsl_ckout_fs const * const s = CFS(f);
  fsl_fstat tmp = fsl_fstat_empty;
  fsl_size_t n = fsl_strlen(zName);
  char * zCopy = NULL;
  int rc;
  if( n>1 && '/'==zName[n-1] ){
    /* A name with a trailing slash, e.g. the checkout's root. A
       storage's names have none, so strip it and keep what it means
       to stat() (on Windows, fsl_stat() only strips it). */
    while( n>1 && '/'==zName[n-1] ) --n;
    zCopy = fsl_strndup(zName, (fsl_int_t)n);
    if( !zCopy ) return FSL_RC_OOM;
  }
  rc = s->xStat(s->state, zCopy ? zCopy : zName, &tmp, derefLinks);
#if !defined(_WIN32)
  if( zCopy && 0==rc ){
    /* POSIX: a trailing slash resolves a final symlink even for
       lstat(), and fails with ENOTDIR unless the name is a
       directory. */
    if( FSL_FSTAT_TYPE_LINK==tmp.type ){
      rc = s->xStat(s->state, zCopy, &tmp, true);
    }
    if( 0==rc && FSL_FSTAT_TYPE_DIR!=tmp.type ){
      rc = fsl_errno_to_rc(ENOTDIR, FSL_RC_IO);
    }
  }
#endif
  fsl_free(zCopy);
  if( 0==rc && fst ) *fst = tmp;
  return rc;
}

fsl_int_t fsl__cfs_size(fsl_cx * const f, char const *zName){
  fsl_fstat fst;
  return 0==fsl__cfs_stat(f, zName, &fst, true) ? (fsl_int_t)fst.size : -1;
}

fsl_time_t fsl__cfs_mtime(fsl_cx * const f, char const *zName){
  fsl_fstat fst;
  return 0==fsl__cfs_stat(f, zName, &fst, true) ? fst.mtime : -1;
}

bool fsl__cfs_is_file(fsl_cx * const f, char const *zName){
  fsl_fstat fst;
  return 0==fsl__cfs_stat(f, zName, &fst, true)
    && FSL_FSTAT_TYPE_FILE==fst.type;
}

bool fsl__cfs_is_file_or_link(fsl_cx * const f, char const *zName){
  fsl_fstat fst;
  return 0==fsl__cfs_stat(f, zName, &fst, false)
    && (FSL_FSTAT_TYPE_FILE==fst.type || FSL_FSTAT_TYPE_LINK==fst.type);
}

bool fsl__cfs_is_symlink(fsl_cx * const f, char const *zName){
  fsl_ckout_fs const * const s = CFS(f);
  fsl_fstat fst;
  return s->xSymlinkRead
    && 0==fsl__cfs_stat(f, zName, &fst, false)
    && FSL_FSTAT_TYPE_LINK==fst.type;
}

bool fsl__cfs_isexec(fsl_cx * const f, char const *zName){
  fsl_fstat fst;
  return 0==fsl__cfs_stat(f, zName, &fst, true)
    && 0!=(fst.perm & FSL_FSTAT_PERM_EXE);
}

int fsl__cfs_dir_check(fsl_cx * const f, char const *zName){
  fsl_fstat fst;
  if( !zName || fsl__cfs_stat(f, zName, &fst, true) ) return 0;
  return FSL_FSTAT_TYPE_DIR==fst.type ? 1 : -1;
}

/** xDirList() callback for fsl__cfs_dir_is_empty(): stop at the
    first entry. */
static int fsl__cfs_dir_any(void * cbState, char const * zEntry){
  (void)zEntry;
  *(int*)cbState = 1;
  return FSL_RC_BREAK;
}

int fsl__cfs_dir_is_empty(fsl_cx * const f, char const *zName){
  fsl_ckout_fs const * const s = CFS(f);
  int any = 0, rc;
  rc = s->xDirList(s->state, zName, fsl__cfs_dir_any, &any);
  if( rc && FSL_RC_BREAK!=rc ) return -1;
  return any;
}

int fsl__cfs_read(fsl_cx * const f, fsl_b * const dest, char const *zName){
  fsl_ckout_fs const * const s = CFS(f);
  fsl_b_reuse(dest);
  return s->xRead(s->state, zName, dest);
}

int fsl__cfs_write(fsl_cx * const f, fsl_b const * const b,
                   char const *zName){
  fsl_ckout_fs const * const s = CFS(f);
  if( !b || !zName ) return FSL_RC_MISUSE;
  if( b->errCode ) return b->errCode /* as fsl_b_to_filename() */;
  return s->xWrite(s->state, zName, b->mem, b->used);
}

int fsl__cfs_write_blob(fsl_cx * const f, char const *zName,
                        fsl_id_t rid, fsl_b * const content,
                        bool loaded, bool * const pWriteFailed){
  fsl_ckout_fs const * const s = CFS(f);
  int rc;
  if( pWriteFailed ) *pWriteFailed = false;
  if( !zName || rid<=0 || !content ) return FSL_RC_MISUSE;
  if( s->xWriteBlob ){
    rc = s->xWriteBlob(s->state, zName, rid);
  }else{
    rc = loaded ? 0 : fsl_content_get(f, rid, content);
    if( rc ) return rc;
    rc = fsl__cfs_write(f, content, zName);
  }
  if( rc && pWriteFailed ) *pWriteFailed = true;
  return rc;
}

int fsl__cfs_unlink(fsl_cx * const f, char const *zName){
  fsl_ckout_fs const * const s = CFS(f);
  return s->xUnlink(s->state, zName);
}

int fsl__cfs_rename(fsl_cx * const f, char const *zFrom, char const *zTo){
  fsl_ckout_fs const * const s = CFS(f);
  return s->xRename(s->state, zFrom, zTo);
}

int fsl__cfs_rmdir(fsl_cx * const f, char const *zName){
  fsl_ckout_fs const * const s = CFS(f);
  int rc;
  /* As fsl_rmdir(). */
  rc = fsl__cfs_dir_check(f, zName);
  if( rc<1 ) return rc ? FSL_RC_TYPE : FSL_RC_NOT_FOUND;
  return s->xRmdir(s->state, zName);
}

/** fsl_mkdir() through the storage. */
static int fsl__cfs_mkdir(fsl_cx * const f, char const *zName,
                          bool forceFlag){
  fsl_ckout_fs const * const s = CFS(f);
  int rc = fsl__cfs_dir_check(f, zName);
  if( rc<0 ){
    if( !forceFlag ) return FSL_RC_TYPE;
    rc = s->xUnlink(s->state, zName);
    if( rc ) return rc;
  }else if( 0==rc ){
    return s->xMkdir(s->state, zName);
  }
  return 0;
}

int fsl__cfs_mkdir_for_file(fsl_cx * const f, char const *zName,
                            bool forceFlag){
  fsl_b b = fsl_b_empty;
  fsl_size_t n, i;
  char * zCan;
  int rc;
  /* As fsl_mkdir_for_file(). */
  n = fsl_strlen(zName);
  if( n==0 ) return FSL_RC_RANGE;
  else if( n<2 ) return 0;
  rc = fsl_file_canonical_name(zName, &b, true);
  zCan = fsl_b_str(&b);
  n = b.used;
  for( i = 1; 0==rc && i<n; ++i ){
    if( '/'==zCan[i] ){
#if defined(_WIN32) || defined(__CYGWIN__)
      /* Skip a drive letter, e.g. the C: of C:/dir/file.txt. */
      if( 2==i && ':'==zCan[1] ) continue;
#endif
      zCan[i] = 0;
      rc = fsl__cfs_dir_check(f, zCan);
      rc = (0>=rc) ? fsl__cfs_mkdir(f, zCan, forceFlag) : 0;
      zCan[i] = '/';
    }
  }
  fsl_b_clear(&b);
  return rc;
}

int fsl__cfs_exec_set(fsl_cx * const f, char const *zName, bool isExec){
  fsl_ckout_fs const * const s = CFS(f);
  fsl_fstat fst;
  if( !s->xExecSet ) return 0;
  /* As fsl_file_exec_set(): only regular files have the bit. */
  {
    int const rc = fsl__cfs_stat(f, zName, &fst, true);
    if( rc ) return rc;
  }
  if( FSL_FSTAT_TYPE_FILE!=fst.type ) return 0;
  return s->xExecSet(s->state, zName, isExec);
}

int fsl__cfs_mtime_set(fsl_cx * const f, char const *zName,
                       fsl_time_t mtime){
  fsl_ckout_fs const * const s = CFS(f);
  if( !zName || !*zName ) return FSL_RC_MISUSE;
  if( !s->xMtimeSet ) return 0;
  if( mtime<0 ) mtime = (fsl_time_t)time(0);
  return s->xMtimeSet(s->state, zName, mtime);
}

int fsl__cfs_copy(fsl_cx * const f, char const *zFrom, char const *zTo){
  fsl_ckout_fs const * const s = CFS(f);
  fsl_b b = fsl_b_empty;
  int rc;
  if( s->xCopy ) return s->xCopy(s->state, zFrom, zTo);
  /* As fsl_file_copy(): create zTo's directory, copy the bytes, and
     carry over the executable bit. */
  rc = fsl__cfs_read(f, &b, zFrom);
  if( 0==rc ) rc = fsl__cfs_mkdir_for_file(f, zTo, false);
  if( 0==rc ) rc = fsl__cfs_write(f, &b, zTo);
  if( 0==rc && fsl__cfs_isexec(f, zFrom) ){
    fsl__cfs_exec_set(f, zTo, true);
  }
  fsl_b_clear(&b);
  return rc;
}

/** fsl__cfs_sha1sum() and fsl__cfs_sha3sum(). */
static int fsl__cfs_hash(fsl_cx * const f, char const *zName, bool sha3,
                         fsl_b * const tgt){
  fsl_ckout_fs const * const s = CFS(f);
  fsl_b b = fsl_b_empty;
  int rc;
  if( !zName || !tgt ) return FSL_RC_MISUSE;
  if( s->xHash ){
    fsl_b_reuse(tgt);
    return s->xHash(s->state, zName, sha3, tgt);
  }
  rc = fsl__cfs_read(f, &b, zName);
  if( 0==rc ){
    rc = sha3 ? fsl_sha3sum_buffer(&b, tgt) : fsl_sha1sum_buffer(&b, tgt);
  }
  fsl_b_clear(&b);
  return rc;
}

int fsl__cfs_sha1sum(fsl_cx * const f, char const *zName, fsl_b * const tgt){
  return fsl__cfs_hash(f, zName, false, tgt);
}

int fsl__cfs_sha3sum(fsl_cx * const f, char const *zName, fsl_b * const tgt){
  return fsl__cfs_hash(f, zName, true, tgt);
}

/** xDirList() callback for fsl__cfs_dircrawl_impl(): collects each
    entry's name, NUL-terminated, into the fsl_b passed as cbState. */
static int fsl__cfs_dir_collect(void * cbState, char const * zEntry){
  fsl_b * const b = (fsl_b*)cbState;
  if( '.'==zEntry[0]
      && (!zEntry[1] || ('.'==zEntry[1] && !zEntry[2])) ){
    return 0;
  }
  return fsl_b_append(b, zEntry, (fsl_int_t)fsl_strlen(zEntry)+1);
}

/**
   fsl_dircrawl_impl() through the storage. The directory's entries
   are collected before any of them is visited, so that the storage's
   xDirList() never runs re-entrantly.
*/
static int fsl__cfs_dircrawl_impl(fsl_cx * const f, fsl_b * const dbuf,
                                  fsl_dircrawl_f cb,
                                  fsl_dircrawl_state * const dst,
                                  unsigned int depth){
  fsl_ckout_fs const * const s = CFS(f);
  fsl_size_t const dPos = dbuf->used;
  fsl_b names = fsl_b_empty;
  fsl_fstat fst = fsl_fstat_empty;
  fsl_size_t i;
  int rc;
  if( depth>20 ) return FSL_RC_RANGE;
  rc = s->xDirList(s->state, fsl_b_cstr(dbuf), fsl__cfs_dir_collect, &names);
  for( i = 0; 0==rc && i<names.used; ){
    char const * const z = (char const *)names.mem + i;
    fsl_size_t newLen;
    i += fsl_strlen(z) + 1;
    dbuf->used = dPos;
    rc = fsl_b_appendf(dbuf, "/%s", z);
    if( rc ) break;
    newLen = dbuf->used;
    if( fsl__cfs_stat(f, fsl_b_cstr(dbuf), &fst, false) ){
      continue /* As fsl_dircrawl(): skip stat errors. */;
    }
    switch( fst.type ){
      case FSL_FSTAT_TYPE_LINK:
      case FSL_FSTAT_TYPE_DIR:
      case FSL_FSTAT_TYPE_FILE:
        break;
      default:
        continue;
    }
    dbuf->mem[dbuf->used = dPos] = 0;
    dst->absoluteDir = (char const *)dbuf->mem;
    dst->entryName = z;
    dst->entryType = fst.type;
    dst->depth = depth;
    rc = cb(dst);
    if( 0==rc ){
      dbuf->mem[dbuf->used] = '/';
      dbuf->used = newLen;
      if( FSL_FSTAT_TYPE_DIR==fst.type ){
        rc = fsl__cfs_dircrawl_impl(f, dbuf, cb, dst, depth+1);
      }
    }else if( FSL_RC_NOOP==rc ){
      rc = 0;
    }
  }
  dbuf->used = dPos;
  if( dbuf->mem ) dbuf->mem[dPos] = 0;
  fsl_b_clear(&names);
  return rc;
}

int fsl__cfs_dircrawl(fsl_cx * const f, char const *zDir,
                      fsl_dircrawl_f callback, void * cbState){
  fsl_b dbuf = fsl_b_empty;
  fsl_fstat fst = fsl_fstat_empty;
  fsl_dircrawl_state dst;
  int rc;
  /* As fsl_dircrawl(). */
  rc = fsl_file_canonical_name(zDir, &dbuf, false);
  if( 0==rc && dbuf.used && '/'==dbuf.mem[dbuf.used-1] ){
    dbuf.mem[--dbuf.used] = 0;
  }
  memset(&dst, 0, sizeof(dst));
  dst.callbackState = cbState;
  if( 0==rc ) rc = fsl__cfs_stat(f, fsl_b_cstr(&dbuf), &fst, false);
  if( 0==rc && FSL_FSTAT_TYPE_DIR!=fst.type ) rc = FSL_RC_TYPE;
  if( 0==rc ){
    rc = fsl__cfs_dircrawl_impl(f, &dbuf, callback, &dst, 1);
    if( FSL_RC_BREAK==rc ) rc = 0;
  }
  fsl_b_clear(&dbuf);
  return rc;
}

int fsl__cfs_symlink_read(fsl_cx * const f, fsl_b * const tgt,
                          char const *zName){
  fsl_ckout_fs const * const s = CFS(f);
  if( !s->xSymlinkRead ) return fsl__cfs_read(f, tgt, zName);
  fsl_b_reuse(tgt);
  return s->xSymlinkRead(s->state, zName, tgt);
}

int fsl__cfs_symlink_create(fsl_cx * const f, char const *zTarget,
                            char const *zLink, bool realLink){
  int rc;
  fsl_ckout_fs const * const s = CFS(f);
  rc = fsl__cfs_mkdir_for_file(f, zLink, false);
  if( 0==rc && realLink && s->xSymlinkCreate ){
    rc = s->xSymlinkCreate(s->state, zTarget, zLink);
  }else if( 0==rc ){
    /* As fsl_symlink_create() with realLink false. */
    fsl_b content = fsl_b_empty;
    fsl_b_external(&content, zTarget, -1);
    fsl__cfs_unlink(f, zLink);
    rc = fsl__cfs_write(f, &content, zLink);
  }
  return rc;
}

int fsl__cfs_symlink_copy(fsl_cx * const f, char const *zFrom,
                          char const *zTo, bool realLink){
  fsl_b b = fsl_b_empty;
  int rc;
  rc = fsl__cfs_symlink_read(f, &b, zFrom);
  if( 0==rc ) rc = fsl__cfs_symlink_create(f, fsl_b_cstr(&b), zTo,
                                           realLink);
  fsl_b_clear(&b);
  return rc;
}

#undef CFS
