/**
   One level of undo and redo (see undo.h), built on the stash.

   An undo record has two slots: 'cur', the record undo or redo
   uses, and 'new', which an operation in progress fills and which
   replaces 'cur' when the operation succeeds. Each slot holds the
   checkout version before the operation (preRid), the version and a
   fingerprint of the local state after it (postRid, fprint), a stash
   snapshot of the local changes before it, copies of vfile and
   vmerge before it, and the stashes it removed or added, to put back
   or take away.

   The TEMP table fx_undo_active marks an operation in progress on
   this connection. Operations which run inside another one, e.g. the
   update which (stash goto) runs, or the revert which a stash save
   runs, find it and record nothing of their own. A NULL label in it
   means recording is suppressed altogether.
*/
#include <assert.h>
#include <string.h>

/* The tables are qualified with the checkout schema's name, "ckout",
   so that they land in the checkout db even when the main db is a host
   application's (fsl_cx_host_db()), or are that db's prefixed tables
   (fsl_repo_open_ckout_opt::hostTablePrefix). */
static char const * const fsl__undo_schema =
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo("
  "  slot TEXT PRIMARY KEY, label TEXT, isRedo INTEGER,"
  "  preRid INTEGER, postRid INTEGER, fprint TEXT, ctime TIMESTAMP);"
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo_vmerge("
  "  slot TEXT, id INTEGER, merge INTEGER, mhash TEXT);"
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo_vfile("
  "  slot TEXT, id INTEGER, vid INTEGER, chnged INT, deleted BOOLEAN,"
  "  isexe BOOLEAN, islink BOOLEAN, rid INTEGER, mrid INTEGER,"
  "  mtime INTEGER, pathname TEXT, origname TEXT, mhash TEXT);"
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo_stash("
  "  slot TEXT PRIMARY KEY, vid INTEGER, hash TEXT, comment TEXT,"
  "  ctime TIMESTAMP);"
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo_stashfile("
  "  slot TEXT, isAdded BOOLEAN, isRemoved BOOLEAN, isExec BOOLEAN,"
  "  isLink BOOLEAN, rid INTEGER, hash TEXT, origname TEXT,"
  "  newname TEXT, delta BLOB);"
  /* Stashes to put back (act='restore') or take away (act='drop'). */
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo_keepstash("
  "  slot TEXT, act TEXT, stashid INTEGER, vid INTEGER, hash TEXT,"
  "  comment TEXT, ctime TIMESTAMP);"
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo_keepstashfile("
  "  slot TEXT, stashid INTEGER, isAdded BOOLEAN, isRemoved BOOLEAN,"
  "  isExec BOOLEAN, isLink BOOLEAN, rid INTEGER, hash TEXT,"
  "  origname TEXT, newname TEXT, delta BLOB);"
  /* Unmanaged files to write back (see fsl__undo_save_extras()). */
  "CREATE TABLE IF NOT EXISTS {{dbname.ckout}}.fsl_undo_extra("
  "  slot TEXT, pathname TEXT, isExec BOOLEAN, content BLOB);"
  "CREATE TEMP TABLE IF NOT EXISTS {{temp.fx_undo_active}}(label TEXT);";

static char const * const fsl__undo_tables_list[] = {
  "fsl_undo", "fsl_undo_vmerge", "fsl_undo_vfile",
  "fsl_undo_stash", "fsl_undo_stashfile",
  "fsl_undo_keepstash", "fsl_undo_keepstashfile", "fsl_undo_extra", NULL
};

static int fsl__undo_tables(fsl_cx * const f){
  fsl_id_t dummy = 0;
  /* fsl_stash_latest() creates the stash tables, which undo uses. */
  int rc = fsl_stash_latest(f, &dummy);
  return rc ? rc : fsl_cx_exec_multi(f, fsl__undo_schema);
}

/**
   Runs zFmt, an UPDATE or DELETE whose "%b" is the qualified name of
   each undo table in turn and whose "%Q" is zSlot, for each of them.
*/
static int fsl__undo_tables_each(fsl_cx * const f, char const * zFmt,
                                 char const * zSlot){
  fsl_b * const name = fsl__cx_scratchpad(f);
  int rc = 0;
  for(int i = 0; !rc && fsl__undo_tables_list[i]; ++i){
    fsl_b_reuse(name);
    rc = fsl__db_table_name(f->dbMain, FSL_DBROLE_CKOUT,
                            fsl__undo_tables_list[i], true, name);
    if(rc) rc = fsl_cx_err_set(f, rc, NULL);
    else rc = fsl_cx_exec(f, zFmt, name, zSlot);
  }
  fsl__cx_scratchpad_yield(f, name);
  return rc;
}

static int fsl__undo_slot_clear(fsl_cx * const f, char const * zSlot){
  return fsl__undo_tables_each(f, "DELETE FROM %b WHERE slot=%Q", zSlot);
}

/** Replaces slot 'cur' with slot 'new'. */
static int fsl__undo_promote(fsl_cx * const f){
  int rc = fsl__undo_slot_clear(f, "cur");
  return rc ? rc : fsl__undo_tables_each(f, "UPDATE %b SET slot=%Q"
                                         " WHERE slot='new'", "cur");
}

/**
   Computes a fingerprint of the checkout's local state into tgt: its
   version, the managed files which differ from it with their on-disk
   hashes, and the merge state. Anything which changes it after an
   operation would be lost by undoing that operation.
*/
static int fsl__undo_fprint(fsl_cx * const f, fsl_b * const tgt){
  fsl_b * const acc = fsl_cx_b_borrow(f);
  fsl_b * const h = fsl_cx_b_borrow(f);
  fsl_b * const path = fsl_cx_b_borrow(f);
  fsl_stmt q = fsl_stmt_empty;
  int rc;
  if( !acc || !h || !path ){
    rc = f->error.code;
    goto end;
  }
  rc = fsl_vfile_changes_scan(f, 0, 0);
  if(!rc) rc = fsl_b_appendf(acc, "rid=%" FSL_ID_T_PFMT "\n",
                             f->db.ckout.rid);
  if(!rc) rc = fsl_cx_prepare(f, &q,
    "SELECT pathname, deleted, coalesce(origname,''), rid, chnged"
    " FROM {{dbname.ckout}}.vfile WHERE vid=%" FSL_ID_T_PFMT
    " AND (chnged OR deleted OR origname NOT NULL OR rid==0)"
    " ORDER BY pathname", f->db.ckout.rid);
  while(fsl__cx_stmt_step_each(f, &q, &rc)){
    char const * const zName = fsl_stmt_g_text(&q, 0, NULL);
    bool const deleted = !!fsl_stmt_g_int32(&q, 1);
    fsl_b_reuse(h);
    if(!deleted){
      fsl_b_reuse(path);
      rc = fsl_b_appendf(path, "%s%s", f->db.ckout.dir, zName);
      if(!rc){
        int const rcHash = fsl__cfs_sha3sum(f, fsl_b_cstr(path), h);
        /* A missing file hashes as nothing. */
        if(rcHash && FSL_RC_NOT_FOUND!=rcHash) rc = rcHash;
        if(rcHash) fsl_b_reuse(h);
      }
    }
    if(!rc) rc = fsl_b_appendf(acc, "%s %d %s %d %d %b\n", zName,
                               (int)deleted, fsl_stmt_g_text(&q, 2, NULL),
                               (int)fsl_stmt_g_id(&q, 3),
                               fsl_stmt_g_int32(&q, 4), h);
  }
  fsl_stmt_finalize(&q);
  if(!rc) rc = fsl_cx_prepare(f, &q,
    "SELECT id, merge, coalesce(mhash,'') FROM {{dbname.ckout}}.vmerge"
    " ORDER BY id, merge, mhash");
  while(fsl__cx_stmt_step_each(f, &q, &rc)){
    rc = fsl_b_appendf(acc, "vmerge %d %d %s\n",
                       (int)fsl_stmt_g_id(&q, 0), (int)fsl_stmt_g_id(&q, 1),
                       fsl_stmt_g_text(&q, 2, NULL));
  }
  fsl_stmt_finalize(&q);
  if(!rc){
    fsl_b_reuse(tgt);
    rc = fsl_sha3sum_buffer(acc, tgt);
  }
  end:
  fsl_cx_b_return(f, acc);
  fsl_cx_b_return(f, h);
  fsl_cx_b_return(f, path);
  return rc;
}

/**
   Completes a snapshot with what a stash leaves out but undo needs:
   each file's actual executable bit, where the stash has vfile's, and
   the content of a file which was removed from management but is
   still on disk, which the stash does not store. Such content goes in
   the delta column, which is otherwise NULL for a removed file.
*/
static int fsl__undo_snapshot_disk(fsl_cx * const f, char const * zSlot){
  fsl_stmt q = fsl_stmt_empty;
  fsl_b * const path = fsl_cx_b_borrow(f);
  fsl_b * const content = fsl_cx_b_borrow(f);
  int rc = (path && content) ? 0 : f->error.code;
  if(!rc) rc = fsl_cx_prepare(f, &q,
    "SELECT rowid, isRemoved, newname FROM {{dbname.ckout}}.fsl_undo_stashfile"
    " WHERE slot=%Q AND NOT isLink", zSlot);
  while(fsl__cx_stmt_step_each(f, &q, &rc)){
    fsl_int_t const rowid = fsl_stmt_g_int64(&q, 0);
    fsl_b_reuse(path);
    rc = fsl_b_appendf(path, "%s%s", f->db.ckout.dir,
                       fsl_stmt_g_text(&q, 2, NULL));
    if(rc) break;
    if(!fsl_stmt_g_int32(&q, 1)){
      rc = fsl_cx_exec(f, "UPDATE {{dbname.ckout}}.fsl_undo_stashfile SET isExec=%d"
                       " WHERE rowid=%" FSL_INT_T_PFMT,
                       (int)fsl__cfs_isexec(f, fsl_b_cstr(path)), rowid);
    }else if(fsl__cfs_is_file(f, fsl_b_cstr(path))){
      fsl_stmt * up = NULL;
      fsl_b_reuse(content);
      rc = fsl__cfs_read(f, content, fsl_b_cstr(path));
      if(!rc) rc = fsl_cx_prepare_cached(f, &up,
        "UPDATE {{dbname.ckout}}.fsl_undo_stashfile SET delta=?1, isExec=?2"
        " WHERE rowid=?3 /*%s()*/", __func__);
      if(!rc) rc = fsl_stmt_bind_blob(up, 1, content->mem
                                      ? (void*)content->mem : (void*)"",
                                      (int)content->used, false);
      if(!rc) rc = fsl_stmt_bind_int32(up, 2,
                                       fsl__cfs_isexec(f, fsl_b_cstr(path)));
      if(!rc) rc = fsl_stmt_bind_int64(up, 3, rowid);
      if(!rc) rc = fsl_stmt_step(up)==FSL_RC_STEP_DONE
        ? 0 : fsl_cx_uplift_db_error2(f, up->db, FSL_RC_DB);
      if(up) fsl_stmt_cached_yield(up);
    }
  }
  fsl_stmt_finalize(&q);
  fsl_cx_b_return(f, path);
  fsl_cx_b_return(f, content);
  return rc;
}

/**
   Saves the local changes as a stash snapshot in the given slot,
   then takes that stash out of the stash list, so that it does not
   show up there or in (fossil stash list).
*/
static int fsl__undo_snapshot(fsl_cx * const f, char const * zSlot){
  fsl_stash_save_opt opt = fsl_stash_save_opt_empty;
  fsl_id_t sid = 0;
  int rc;
  opt.keepChanges = true;
  opt.comment = "undo snapshot";
  rc = fsl_stash_save(f, &opt, &sid);
  if(FSL_RC_NOOP==rc){
    /* No local changes: an empty snapshot. */
    fsl_cx_err_reset(f);
    return 0;
  }
  if(!rc) rc = fsl_cx_exec_multi(f,
    "INSERT INTO {{dbname.ckout}}.fsl_undo_stash(slot,vid,hash,comment,ctime)"
    " SELECT %Q, vid, hash, comment, ctime FROM {{dbname.ckout}}.stash"
    " WHERE stashid=%" FSL_ID_T_PFMT ";"
    "INSERT INTO {{dbname.ckout}}.fsl_undo_stashfile(slot,isAdded,isRemoved,isExec,isLink,"
    "  rid,hash,origname,newname,delta)"
    " SELECT %Q, isAdded, isRemoved, isExec, isLink, rid, hash, origname,"
    "  newname, delta FROM {{dbname.ckout}}.stashfile WHERE stashid=%" FSL_ID_T_PFMT ";"
    "DELETE FROM {{dbname.ckout}}.stash WHERE stashid=%" FSL_ID_T_PFMT ";"
    "DELETE FROM {{dbname.ckout}}.stashfile WHERE stashid=%" FSL_ID_T_PFMT ";",
    zSlot, sid, zSlot, sid, sid, sid);
  /* Give the stash ID back. */
  if(!rc) rc = fsl_config_set_id(f, FSL_CONFDB_CKOUT, "stash-next", sid);
  if(!rc) rc = fsl__undo_snapshot_disk(f, zSlot);
  return rc;
}

/**
   Records the current state in the given slot, with the given label:
   the checkout version, the merge state and a snapshot of the local
   changes.
*/
static int fsl__undo_capture(fsl_cx * const f, char const * zSlot,
                             char const * zLabel){
  int rc = fsl__undo_slot_clear(f, zSlot);
  if(!rc) rc = fsl_cx_exec(f,
    "INSERT INTO {{dbname.ckout}}.fsl_undo(slot,label,isRedo,preRid,postRid,fprint,ctime)"
    " VALUES(%Q,%Q,0,%" FSL_ID_T_PFMT ",0,NULL,julianday('now'))",
    zSlot, zLabel, f->db.ckout.rid);
  if(!rc) rc = fsl_cx_exec(f,
    "INSERT INTO {{dbname.ckout}}.fsl_undo_vmerge(slot,id,merge,mhash)"
    " SELECT %Q, id, merge, mhash FROM {{dbname.ckout}}.vmerge", zSlot);
  if(!rc) rc = fsl__undo_snapshot(f, zSlot);
  /* The snapshot holds file contents but not the vfile bookkeeping,
     e.g. which files a merge changed, so keep a copy of that, as
     fossil(1)'s undo_vfile does. Taken after the snapshot, whose
     changes scan brings vfile up to date. */
  if(!rc) rc = fsl_cx_exec(f,
    "INSERT INTO {{dbname.ckout}}.fsl_undo_vfile(slot,%s) SELECT %Q,%s FROM {{dbname.ckout}}.vfile",
    "id,vid,chnged,deleted,isexe,islink,rid,mrid,mtime,pathname,origname,mhash", zSlot, "id,vid,chnged,deleted,isexe,islink,rid,mrid,mtime,pathname,origname,mhash");
  return rc;
}

/**
   Copies stash stashId, or all stashes if it is negative, into the
   given slot's list of stashes to act on.
*/
static int fsl__undo_copy_stash(fsl_cx * const f, char const * zSlot,
                                char const * zAct, fsl_id_t stashId){
  return fsl_cx_exec_multi(f,
    "INSERT INTO {{dbname.ckout}}.fsl_undo_keepstash(slot,act,stashid,vid,hash,comment,ctime)"
    " SELECT %Q, %Q, stashid, vid, hash, comment, ctime FROM {{dbname.ckout}}.stash"
    " WHERE (%" FSL_ID_T_PFMT "<0 OR stashid=%" FSL_ID_T_PFMT ")"
    " AND stashid NOT IN (SELECT stashid FROM {{dbname.ckout}}.fsl_undo_keepstash"
    "                     WHERE slot=%Q);"
    "INSERT INTO {{dbname.ckout}}.fsl_undo_keepstashfile(slot,stashid,isAdded,isRemoved,"
    "  isExec,isLink,rid,hash,origname,newname,delta)"
    " SELECT %Q, stashid, isAdded, isRemoved, isExec, isLink, rid, hash,"
    "  origname, newname, delta FROM {{dbname.ckout}}.stashfile"
    " WHERE (%" FSL_ID_T_PFMT "<0 OR stashid=%" FSL_ID_T_PFMT ")"
    " AND stashid NOT IN (SELECT stashid FROM {{dbname.ckout}}.fsl_undo_keepstashfile"
    "                     WHERE slot=%Q);",
    zSlot, zAct, stashId, stashId, zSlot,
    zSlot, stashId, stashId, zSlot);
}

/**
   Returns true if an operation is being recorded on f's connection,
   setting *recording to whether it records (as opposed to having
   suppressed recording).
*/
static bool fsl__undo_active(fsl_cx * const f, bool * recording){
  fsl_db * const db = fsl_cx_db_ckout(f);
  *recording = false;
  if(!db || !fsl_db_exists(db, "SELECT 1 FROM {{temp.fx_undo_active}}")) return false;
  *recording = fsl_db_exists(db, "SELECT 1 FROM {{temp.fx_undo_active}}"
                             " WHERE label IS NOT NULL");
  return true;
}

int fsl__undo_begin(fsl_cx * const f, char const * zLabel,
                    bool * const owner){
  bool recording = false;
  int rc;
  *owner = false;
  if(!fsl_cx_db_ckout(f)) return 0;
  rc = fsl__undo_tables(f);
  if(rc || fsl__undo_active(f, &recording)) return rc;
  rc = fsl_cx_exec(f, "INSERT INTO {{temp.fx_undo_active}}(label) VALUES(%Q)",
                   zLabel);
  if(rc) return rc;
  *owner = true;
  if(zLabel){
    /* One transaction, so that a failure cannot leave the snapshot's
       stash behind in the stash list. */
    rc = fsl_cx_txn_begin(f);
    if(!rc){
      rc = fsl__undo_capture(f, "new", zLabel);
      int const rc2 = fsl_cx_txn_end(f, !!rc);
      if(!rc) rc = rc2;
    }
  }
  return rc;
}

int fsl__undo_keep_stash(fsl_cx * const f, fsl_id_t stashId){
  bool recording = false;
  if(!fsl__undo_active(f, &recording) || !recording) return 0;
  return fsl__undo_copy_stash(f, "new", "restore", stashId);
}

int fsl__undo_end(fsl_cx * const f, int rc, bool owner){
  bool recording = false;
  int rc2 = 0;
  if(!owner) return rc;
  fsl__undo_active(f, &recording);
  if(recording){
    if(0==rc){
      fsl_b * const fp = fsl_cx_b_borrow(f);
      rc2 = fp ? fsl__undo_fprint(f, fp) : f->error.code;
      if(!rc2) rc2 = fsl_cx_exec(f,
        "UPDATE {{dbname.ckout}}.fsl_undo SET postRid=%" FSL_ID_T_PFMT ", fprint=%Q"
        " WHERE slot='new'", f->db.ckout.rid, fsl_b_cstr(fp));
      if(!rc2) rc2 = fsl__undo_promote(f);
      fsl_cx_b_return(f, fp);
    }else{
      fsl__undo_slot_clear(f, "new");
    }
  }
  {
    int const rc3 = fsl_cx_exec(f, "DELETE FROM {{temp.fx_undo_active}}");
    if(!rc2) rc2 = rc3;
  }
  return rc ? rc : rc2;
}

int fsl_undo_state(fsl_cx * const f, fsl_undo_e * state, char ** zLabel){
  fsl_db * const db = fsl_needs_ckout(f);
  fsl_stmt q = fsl_stmt_empty;
  int rc;
  if(!db) return FSL_RC_NOT_A_CKOUT;
  *state = FSL_UNDO_NONE;
  if(zLabel) *zLabel = NULL;
  rc = fsl__undo_tables(f);
  if(!rc) rc = fsl_cx_prepare(f, &q, "SELECT isRedo, label FROM {{dbname.ckout}}.fsl_undo"
                              " WHERE slot='cur'");
  if(rc) return rc;
  if(FSL_RC_STEP_ROW==fsl_stmt_step(&q)){
    *state = fsl_stmt_g_int32(&q, 0) ? FSL_UNDO_REDO : FSL_UNDO_UNDO;
    if(zLabel){
      *zLabel = fsl_strdup(fsl_stmt_g_text(&q, 1, NULL));
      if(!*zLabel) rc = FSL_RC_OOM;
    }
  }
  fsl_stmt_finalize(&q);
  return rc;
}

int fsl_undo_reset(fsl_cx * const f){
  fsl_db * const db = fsl_needs_ckout(f);
  int rc;
  if(!db) return FSL_RC_NOT_A_CKOUT;
  rc = fsl__undo_tables(f);
  if(!rc) rc = fsl__undo_slot_clear(f, "cur");
  if(!rc) rc = fsl__undo_slot_clear(f, "new");
  return rc;
}

/**
   Writes back the files of the snapshot in slot 'cur', exactly as
   they were, over a clean checkout of its version: each one's content
   is its baseline plus its stashed delta, or, for an added file, the
   stashed content itself. Then restores the vfile and vmerge
   bookkeeping saved with the snapshot.
*/
static int fsl__undo_restore(fsl_cx * const f){
  fsl_stmt q = fsl_stmt_empty;
  fsl_b * const path = fsl_cx_b_borrow(f);
  fsl_b base = fsl_b_empty;
  fsl_b content = fsl_b_empty;
  bool const allowLinks = fsl_cx_allows_symlinks(f, false);
  int rc = path ? 0 : f->error.code;
  if(!rc) rc = fsl_cx_prepare(f, &q,
    "SELECT isRemoved, isExec, isLink, origname, newname, delta,"
    " (SELECT rid FROM {{dbname.repo}}.blob WHERE uuid=s.hash), s.hash IS NULL,"
    " delta IS NULL FROM {{dbname.ckout}}.fsl_undo_stashfile s WHERE slot='cur'");
  while(fsl__cx_stmt_step_each(f, &q, &rc)){
    bool const isRemoved = !!fsl_stmt_g_int32(&q, 0);
    bool const isExec = !!fsl_stmt_g_int32(&q, 1);
    bool const isLink = !!fsl_stmt_g_int32(&q, 2);
    char const * const zOrig = fsl_stmt_g_text(&q, 3, NULL);
    char const * const zNew = fsl_stmt_g_text(&q, 4, NULL);
    fsl_id_t const rid = fsl_stmt_g_id(&q, 6);
    bool const isAdded = !!fsl_stmt_g_int32(&q, 7);
    void const * pDelta = NULL;
    fsl_size_t nDelta = 0;
    fsl_b delta = fsl_b_empty;
    if(fsl_strcmp(zOrig, zNew)){
      fsl_b_reuse(path);
      rc = fsl_b_appendf(path, "%s%s", f->db.ckout.dir, zOrig);
      if(rc) break;
      fsl__cfs_unlink(f, fsl_b_cstr(path));
    }
    fsl_b_reuse(path);
    rc = fsl_b_appendf(path, "%s%s", f->db.ckout.dir, zNew);
    if(rc) break;
    if(isRemoved && fsl_stmt_g_int32(&q, 8)){
      /* Removed, and not on disk. */
      fsl__cfs_unlink(f, fsl_b_cstr(path));
      continue;
    }
    fsl_stmt_get_blob(&q, 5, &pDelta, &nDelta);
    fsl_b_external(&delta, pDelta, (fsl_int_t)nDelta);
    fsl_b_reuse(&content);
    if(isAdded || isRemoved){
      /* The whole content: an added file, or a removed one which was
         still on disk. */
      rc = delta.used ? fsl_b_append(&content, delta.mem, delta.used) : 0;
    }else if(rid<=0){
      rc = fsl_cx_err_set(f, FSL_RC_NOT_FOUND, "The baseline of %s is "
                          "not in the repository.", zNew);
    }else{
      rc = fsl_content_get(f, rid, &base);
      if(!rc) rc = fsl_b_delta_apply(&base, &delta, &content);
    }
    if(rc) break;
    fsl__cfs_unlink(f, fsl_b_cstr(path));
    if(isLink){
      rc = fsl__cfs_symlink_create(f, fsl_b_cstr(&content), fsl_b_cstr(path),
                              allowLinks);
    }else{
      rc = fsl__cfs_mkdir_for_file(f, fsl_b_cstr(path), true);
      if(!rc) rc = fsl__cfs_write(f, &content, fsl_b_cstr(path));
      if(!rc) rc = fsl__cfs_exec_set(f, fsl_b_cstr(path), isExec);
    }
    if(rc){
      rc = fsl_cx_err_set(f, rc, "Error %R writing %s", rc, zNew);
      break;
    }
  }
  fsl_stmt_finalize(&q);
  fsl_b_clear(&base);
  fsl_b_clear(&content);
  fsl_cx_b_return(f, path);
  /* The bookkeeping, with mtime=0 so that the next changes scan looks
     at every file. */
  if(!rc) rc = fsl_cx_exec_multi(f,
    "DELETE FROM {{dbname.ckout}}.vfile;"
    "INSERT INTO {{dbname.ckout}}.vfile(id,vid,chnged,deleted,isexe,islink,rid,mrid,mtime,pathname,origname,mhash)"
    " SELECT id,vid,chnged,deleted,isexe,islink,rid,mrid,mtime,pathname,origname,mhash FROM {{dbname.ckout}}.fsl_undo_vfile WHERE slot='cur';"
    "UPDATE {{dbname.ckout}}.vfile SET mtime=0;"
    "DELETE FROM {{dbname.ckout}}.vmerge;"
    "INSERT INTO {{dbname.ckout}}.vmerge(id,merge,mhash)"
    " SELECT id, merge, mhash FROM {{dbname.ckout}}.fsl_undo_vmerge WHERE slot='cur';");
  return rc;
}

/**
   Called while recording the opposite state ('new') just before
   restoring slot 'cur': saves each unmanaged file which sits at a
   path that 'cur' manages, under its current or original name. The
   restore would overwrite or move it, e.g. a file left behind by an
   update which dropped a rename, and the snapshot holds only managed
   files.
*/
static int fsl__undo_save_extras(fsl_cx * const f){
  fsl_stmt q = fsl_stmt_empty;
  fsl_b * const path = fsl_cx_b_borrow(f);
  fsl_b * const content = fsl_cx_b_borrow(f);
  int rc = (path && content) ? 0 : f->error.code;
  if(!rc) rc = fsl_cx_prepare(f, &q,
    "SELECT DISTINCT p FROM ("
    "  SELECT pathname AS p FROM {{dbname.ckout}}.fsl_undo_vfile WHERE slot='cur'"
    "  UNION SELECT origname FROM {{dbname.ckout}}.fsl_undo_vfile"
    "   WHERE slot='cur' AND origname IS NOT NULL)"
    " WHERE p NOT IN (SELECT pathname FROM {{dbname.ckout}}.vfile)"
    "   AND p NOT IN (SELECT origname FROM {{dbname.ckout}}.vfile WHERE origname IS NOT NULL)");
  while(fsl__cx_stmt_step_each(f, &q, &rc)){
    char const * const zName = fsl_stmt_g_text(&q, 0, NULL);
    fsl_b_reuse(path);
    rc = fsl_b_appendf(path, "%s%s", f->db.ckout.dir, zName);
    if(rc || !fsl__cfs_is_file(f, fsl_b_cstr(path))) continue;
    fsl_b_reuse(content);
    rc = fsl__cfs_read(f, content, fsl_b_cstr(path));
    if(!rc){
      fsl_stmt * up = NULL;
      rc = fsl_cx_prepare_cached(f, &up,
        "INSERT INTO {{dbname.ckout}}.fsl_undo_extra(slot,pathname,isExec,content)"
        " VALUES('new',?1,?2,?3) /*%s()*/", __func__);
      if(!rc) rc = fsl_stmt_bind_text(up, 1, zName, -1, false);
      if(!rc) rc = fsl_stmt_bind_int32(up, 2,
                                       fsl__cfs_isexec(f, fsl_b_cstr(path)));
      if(!rc) rc = fsl_stmt_bind_blob(up, 3, content->mem
                                      ? (void*)content->mem : (void*)"",
                                      (int)content->used, false);
      if(!rc) rc = fsl_stmt_step(up)==FSL_RC_STEP_DONE
        ? 0 : fsl_cx_uplift_db_error2(f, up->db, FSL_RC_DB);
      if(up) fsl_stmt_cached_yield(up);
    }
  }
  fsl_stmt_finalize(&q);
  fsl_cx_b_return(f, path);
  fsl_cx_b_return(f, content);
  return rc;
}

/**
   Writes back the unmanaged files saved with slot 'cur'.
*/
static int fsl__undo_restore_extras(fsl_cx * const f){
  fsl_stmt q = fsl_stmt_empty;
  fsl_b * const path = fsl_cx_b_borrow(f);
  int rc = path ? 0 : f->error.code;
  if(!rc) rc = fsl_cx_prepare(f, &q, "SELECT pathname, isExec, content"
                              " FROM {{dbname.ckout}}.fsl_undo_extra WHERE slot='cur'");
  while(fsl__cx_stmt_step_each(f, &q, &rc)){
    void const * pC = NULL;
    fsl_size_t nC = 0;
    fsl_b c = fsl_b_empty;
    fsl_b_reuse(path);
    rc = fsl_b_appendf(path, "%s%s", f->db.ckout.dir,
                       fsl_stmt_g_text(&q, 0, NULL));
    if(rc) break;
    fsl_stmt_get_blob(&q, 2, &pC, &nC);
    fsl_b_external(&c, pC, (fsl_int_t)nC);
    rc = fsl__cfs_mkdir_for_file(f, fsl_b_cstr(path), true);
    if(!rc) rc = fsl__cfs_write(f, &c, fsl_b_cstr(path));
    if(!rc) rc = fsl__cfs_exec_set(f, fsl_b_cstr(path),
                                   !!fsl_stmt_g_int32(&q, 1));
    if(rc) rc = fsl_cx_err_set(f, rc, "Error %R writing %b", rc, path);
  }
  fsl_stmt_finalize(&q);
  fsl_cx_b_return(f, path);
  return rc;
}

int fsl_undo(fsl_cx * const f, bool redo, bool force){
  fsl_db * const db = fsl_needs_ckout(f);
  fsl_stmt q = fsl_stmt_empty;
  fsl_b * const fp = fsl_cx_b_borrow(f);
  fsl_id_t preRid = 0, postRid = 0;
  char * zLabel = NULL;
  char * zFprint = NULL;
  bool inTxn = false, active = false;
  int rc;
  if(!db){
    rc = FSL_RC_NOT_A_CKOUT;
    goto end;
  }
  if(!fp){
    rc = f->error.code;
    goto end;
  }
  rc = fsl_cx_txn_begin(f);
  if(rc) goto end;
  inTxn = true;
  rc = fsl__undo_tables(f);
  if(!rc){
    bool recording = false;
    if(fsl__undo_active(f, &recording)){
      rc = fsl_cx_err_set(f, FSL_RC_MISUSE, "Cannot %s while another "
                          "checkout operation is running.",
                          redo ? "redo" : "undo");
      goto end;
    }
  }
  if(!rc) rc = fsl_cx_prepare(f, &q,
    "SELECT label, preRid, postRid, fprint FROM {{dbname.ckout}}.fsl_undo"
    " WHERE slot='cur' AND isRedo=%d", redo ? 1 : 0);
  if(rc) goto end;
  if(FSL_RC_STEP_ROW==fsl_stmt_step(&q)){
    zLabel = fsl_strdup(fsl_stmt_g_text(&q, 0, NULL));
    preRid = fsl_stmt_g_id(&q, 1);
    postRid = fsl_stmt_g_id(&q, 2);
    zFprint = fsl_strdup(fsl_stmt_g_text(&q, 3, NULL));
    if(!zLabel || !zFprint) rc = FSL_RC_OOM;
  }else{
    rc = fsl_cx_err_set(f, FSL_RC_NOT_FOUND, "Nothing to %s.",
                        redo ? "redo" : "undo");
  }
  fsl_stmt_finalize(&q);
  if(rc) goto end;
  if(postRid!=f->db.ckout.rid){
    rc = fsl_cx_err_set(f, FSL_RC_CONFLICT,
                        "The checkout is no longer on the version which "
                        "%s left it on, so it cannot be %s.",
                        zLabel, redo ? "redone" : "undone");
    goto end;
  }
  rc = fsl__undo_fprint(f, fp);
  if(rc) goto end;
  if(!force && fsl_strcmp(zFprint, fsl_b_cstr(fp))){
    rc = fsl_cx_err_set(f, FSL_RC_CONFLICT,
                        "The checkout changed after %s. %s it would "
                        "discard those changes.", zLabel,
                        redo ? "Redoing" : "Undoing");
    goto end;
  }
  /* From here on, the operations below must not record undo state of
     their own. */
  rc = fsl_cx_exec(f, "INSERT INTO {{temp.fx_undo_active}}(label) VALUES(NULL)");
  if(rc) goto end;
  active = true;
  /* The opposite record: the state now, and the stashes to undo
     this undo's stash changes. */
  rc = fsl__undo_capture(f, "new", zLabel);
  if(!rc) rc = fsl__undo_save_extras(f);
  if(!rc) rc = fsl_cx_exec_multi(f,
    "INSERT INTO {{dbname.ckout}}.fsl_undo_keepstash(slot,act,stashid)"
    " SELECT 'new', 'drop', stashid FROM {{dbname.ckout}}.fsl_undo_keepstash"
    " WHERE slot='cur' AND act='restore';");
  if(!rc){
    rc = fsl_cx_prepare(f, &q, "SELECT stashid FROM {{dbname.ckout}}.fsl_undo_keepstash"
                        " WHERE slot='cur' AND act='drop'");
    while(fsl__cx_stmt_step_each(f, &q, &rc)){
      rc = fsl__undo_copy_stash(f, "new", "restore", fsl_stmt_g_id(&q, 0));
    }
    fsl_stmt_finalize(&q);
  }
  if(rc) goto end;
  /* A revert removes what merges added and unmanages, but keeps, what
     was added by hand, as in fossil(1). The snapshot below rewrites
     any of those which the recorded state has. */
  {
    fsl_ckout_revert_opt ropt = fsl_ckout_revert_opt_empty;
    ropt.relativeToCwd = false;
    rc = fsl_ckout_revert(f, &ropt);
  }
  if(!rc && preRid!=f->db.ckout.rid){
    fsl_ckup_opt uopt = fsl_ckup_opt_empty;
    uopt.checkinRid = preRid;
    rc = fsl_ckout_update(f, &uopt);
  }
  if(!rc) rc = fsl__undo_restore(f);
  if(!rc) rc = fsl__undo_restore_extras(f);
  if(!rc) rc = fsl_cx_exec_multi(f,
    "INSERT OR IGNORE INTO {{dbname.ckout}}.stash(stashid,vid,hash,comment,ctime)"
    " SELECT stashid, vid, hash, comment, ctime FROM {{dbname.ckout}}.fsl_undo_keepstash"
    " WHERE slot='cur' AND act='restore';"
    "INSERT OR IGNORE INTO {{dbname.ckout}}.stashfile(stashid,isAdded,isRemoved,isExec,"
    "  isLink,rid,hash,origname,newname,delta)"
    " SELECT stashid, isAdded, isRemoved, isExec, isLink, rid, hash,"
    "  origname, newname, delta FROM {{dbname.ckout}}.fsl_undo_keepstashfile"
    " WHERE slot='cur' AND stashid IN (SELECT stashid FROM"
    "  {{dbname.ckout}}.fsl_undo_keepstash WHERE slot='cur' AND act='restore');"
    "DELETE FROM {{dbname.ckout}}.stashfile WHERE stashid IN (SELECT stashid FROM"
    "  {{dbname.ckout}}.fsl_undo_keepstash WHERE slot='cur' AND act='drop');"
    "DELETE FROM {{dbname.ckout}}.stash WHERE stashid IN (SELECT stashid FROM"
    "  {{dbname.ckout}}.fsl_undo_keepstash WHERE slot='cur' AND act='drop');");
  if(!rc) rc = fsl__undo_fprint(f, fp);
  if(!rc) rc = fsl_cx_exec(f,
    "UPDATE {{dbname.ckout}}.fsl_undo SET isRedo=%d, postRid=%" FSL_ID_T_PFMT ", fprint=%Q"
    " WHERE slot='new'", redo ? 0 : 1, f->db.ckout.rid, fsl_b_cstr(fp));
  if(!rc) rc = fsl__undo_promote(f);
  end:
  if(active){
    int const rc2 = fsl_cx_exec(f, "DELETE FROM {{temp.fx_undo_active}}");
    if(!rc) rc = rc2;
  }
  fsl_stmt_finalize(&q);
  fsl_free(zLabel);
  fsl_free(zFprint);
  fsl_cx_b_return(f, fp);
  if(inTxn){
    int const rc2 = fsl_cx_txn_end(f, !!rc);
    if(!rc) rc = rc2;
  }
  return rc;
}
