/**
   Bisect sessions (see bisect.h). A port of fossil(1) 2.29's
   src/bisect.c, and, for the path between the good and bad
   check-ins, of its src/path.c path_shortest() and src/pqueue.c.
*/
#include <assert.h>
#include <stdlib.h>
#include <string.h>

const fsl_bisect_state_t fsl_bisect_state_t_empty = {0,0,0,0,0,false};

/** The bisect options, with fossil(1)'s defaults. */
static struct {
  char const * zName;
  char const * zDefault;
} const fsl__bisect_options[] = {
  {"auto-next", "on"},
  {"direct-only", "on"},
  {"display", "chart"},
  {"linear", "off"}
};
#define fsl__bisect_option_count \
  (sizeof(fsl__bisect_options)/sizeof(fsl__bisect_options[0]))

/** fossil(1)'s is_truth(). */
static bool fsl__bisect_is_truth(char const * z){
  static char const * const azOn[] = {"on", "yes", "true"};
  for(unsigned i = 0; i < sizeof(azOn)/sizeof(azOn[0]); ++i){
    if(0==fsl_stricmp(z, azOn[i])) return true;
  }
  return 0!=atoi(z);
}

/** fossil(1)'s is_false(). */
static bool fsl__bisect_is_false(char const * z){
  static char const * const azOff[] = {"off", "no", "false", "0"};
  for(unsigned i = 0; i < sizeof(azOff)/sizeof(azOff[0]); ++i){
    if(0==fsl_stricmp(z, azOff[i])) return true;
  }
  return false;
}

/** Reads vvar entry zName, or returns NULL. Caller frees. */
static char * fsl__bisect_vvar(fsl_cx * const f, char const * zName){
  return fsl_db_g_text(fsl_cx_db_ckout(f), NULL,
                       "SELECT value FROM {{dbname.ckout}}.vvar WHERE name=%Q", zName);
}

static fsl_id_t fsl__bisect_vvar_id(fsl_cx * const f, char const * zName){
  return fsl_db_g_id(fsl_cx_db_ckout(f), 0,
                     "SELECT value FROM {{dbname.ckout}}.vvar WHERE name=%Q", zName);
}

static int fsl__bisect_vvar_set_id(fsl_cx * const f, char const * zName,
                                   fsl_id_t v){
  return fsl_cx_exec(f, "REPLACE INTO {{dbname.ckout}}.vvar(name,value) VALUES(%Q,"
                     "%" FSL_ID_T_PFMT ")", zName, v);
}

int fsl_bisect_option(fsl_cx * const f, char const * zName,
                      char const * zNewValue, char ** zValue){
  char * zKey;
  char * z;
  unsigned i;
  int rc = 0;
  if(!fsl_needs_ckout(f)) return FSL_RC_NOT_A_CKOUT;
  for(i = 0; i < fsl__bisect_option_count; ++i){
    if(0==fsl_strcmp(zName, fsl__bisect_options[i].zName)) break;
  }
  if(i==fsl__bisect_option_count){
    return fsl_cx_err_set(f, FSL_RC_NOT_FOUND, "No such bisect option: %s",
                          zName);
  }
  zKey = fsl_mprintf("bisect-%s", zName);
  if(!zKey) return FSL_RC_OOM;
  if(zNewValue){
    rc = fsl_cx_exec(f, "REPLACE INTO {{dbname.ckout}}.vvar(name,value) VALUES(%Q,%Q)",
                     zKey, zNewValue);
  }
  if(!rc && zValue){
    z = fsl__bisect_vvar(f, zKey);
    *zValue = z ? z : fsl_strdup(fsl__bisect_options[i].zDefault);
    if(!*zValue) rc = FSL_RC_OOM;
  }
  fsl_free(zKey);
  return rc;
}

bool fsl_bisect_option_is_on(fsl_cx * const f, char const * zName){
  char * z = NULL;
  char const * zDflt = "off";
  bool on;
  for(unsigned i = 0; i < fsl__bisect_option_count; ++i){
    if(0==fsl_strcmp(zName, fsl__bisect_options[i].zName)){
      zDflt = fsl__bisect_options[i].zDefault;
      break;
    }
  }
  if(!fsl_cx_db_ckout(f) || fsl_bisect_option(f, zName, NULL, &z)){
    fsl_cx_err_reset(f);
    return fsl__bisect_is_truth(zDflt);
  }
  if(fsl__bisect_is_truth(z)) on = true;
  else if(fsl__bisect_is_false(z)) on = false;
  else on = fsl__bisect_is_truth(zDflt);
  fsl_free(z);
  return on;
}

int fsl_bisect_mark(fsl_cx * const f, fsl_bisect_e verdict, fsl_id_t rid){
  int rc;
  if(!fsl_needs_ckout(f)) return FSL_RC_NOT_A_CKOUT;
  if(rid<=0) rid = f->db.ckout.rid;
  if(rid<=0){
    return fsl_cx_err_set(f, FSL_RC_RANGE, "No check-in to mark.");
  }
  switch(verdict){
    case FSL_BISECT_GOOD:
    case FSL_BISECT_BAD: {
      char const * zKey = FSL_BISECT_GOOD==verdict ? "bisect-good"
        : "bisect-bad";
      /* The log holds good check-ins as positive RIDs, bad ones as
         negative. */
      fsl_id_t const logged = FSL_BISECT_GOOD==verdict ? rid : -rid;
      if(fsl__bisect_vvar_id(f, zKey)==rid) return 0;
      rc = fsl_cx_txn_begin(f);
      if(rc) return rc;
      rc = fsl__bisect_vvar_set_id(f, zKey, rid);
      if(!rc) rc = fsl_cx_exec(f,
        "REPLACE INTO {{dbname.ckout}}.vvar(name,value) VALUES('bisect-log',"
        "COALESCE((SELECT value||' ' FROM {{dbname.ckout}}.vvar WHERE name='bisect-log'),'')"
        " || '%" FSL_ID_T_PFMT "')", logged);
      {
        int const rc2 = fsl_cx_txn_end(f, !!rc);
        if(!rc) rc = rc2;
      }
      return rc;
    }
    case FSL_BISECT_SKIP:
      /* As in fossil(1), this appends only to an existing log. */
      return fsl_cx_exec(f, "UPDATE {{dbname.ckout}}.vvar SET value=value||' s%"
                         FSL_ID_T_PFMT "' WHERE name='bisect-log'", rid);
    default:
      return fsl_cx_err_set(f, FSL_RC_RANGE, "Invalid bisect verdict: %d",
                            (int)verdict);
  }
}

int fsl_bisect_undo(fsl_cx * const f){
  char * zLog;
  char const * z;
  fsl_id_t good = 0, bad = 0;
  fsl_size_t keep = 0;
  int cnt = 0, rc;
  if(!fsl_needs_ckout(f)) return FSL_RC_NOT_A_CKOUT;
  zLog = fsl__bisect_vvar(f, "bisect-log");
  for(z = zLog ? zLog : ""; *z; ){
    while(*z==' ') ++z;
    if(*z){ ++cnt; while(*z && *z!=' ') ++z; }
  }
  if(0==cnt){
    fsl_free(zLog);
    return fsl_cx_err_set(f, FSL_RC_NOT_FOUND,
                          "No previous bisect steps to undo.");
  }
  /* Replay all but the last entry for the good and bad check-ins, and
     keep the log up to the end of the second-to-last one. Skip entries
     are passed over. (fossil(1) 2.29 parses a skip entry as RID 0 and
     takes it as the good check-in, so its undo forgets the good one
     whenever a skip follows it.) */
  z = zLog;
  for(int i = 0; i < cnt-1; ++i){
    fsl_id_t rid;
    while(*z==' ') ++z;
    rid = (fsl_id_t)strtoll(z, NULL, 10);
    if(rid<0) bad = -rid;
    else if(rid>0) good = rid;
    while(*z && *z!=' ') ++z;
  }
  keep = (fsl_size_t)(z - zLog);
  rc = fsl_cx_txn_begin(f);
  if(!rc){
    rc = fsl_cx_exec(f, "UPDATE {{dbname.ckout}}.vvar SET value=substr(value,1,%d)"
                     " WHERE name='bisect-log'", (int)keep);
    if(!rc) rc = fsl__bisect_vvar_set_id(f, "bisect-bad", bad);
    if(!rc) rc = fsl__bisect_vvar_set_id(f, "bisect-good", good);
    int const rc2 = fsl_cx_txn_end(f, !!rc);
    if(!rc) rc = rc2;
  }
  fsl_free(zLog);
  return rc;
}

int fsl_bisect_reset(fsl_cx * const f){
  if(!fsl_needs_ckout(f)) return FSL_RC_NOT_A_CKOUT;
  return fsl_cx_exec(f, "DELETE FROM {{dbname.ckout}}.vvar WHERE name IN"
                     " ('bisect-good','bisect-bad','bisect-log',"
                     "  'bisect-complete','bisect-linear')");
}

int fsl_bisect_state(fsl_cx * const f, fsl_bisect_state_t * st){
  if(!fsl_needs_ckout(f)) return FSL_RC_NOT_A_CKOUT;
  *st = fsl_bisect_state_t_empty;
  st->good = fsl__bisect_vvar_id(f, "bisect-good");
  st->bad = fsl__bisect_vvar_id(f, "bisect-bad");
  st->complete = 0!=fsl__bisect_vvar_id(f, "bisect-complete");
  return 0;
}

/*
  The path search: fossil(1) 2.29's path_shortest() with no branch
  cost and both directions allowed, which is how bisect calls it. Its
  pending nodes are kept in a binary heap, ported from pqueue.c,
  because the order in which the heap returns equal-cost nodes picks
  between equally short paths, and so the midpoint.
*/
typedef struct {
  fsl_vpath_node * node;
  double value;
} fsl__bisect_qe;

typedef struct {
  fsl__bisect_qe * a;
  int cnt;
  int sz;
} fsl__bisect_pq;

static int fsl__bisect_pq_insert(fsl__bisect_pq * const p,
                                 fsl_vpath_node * node, double v){
  int i, j;
  if(p->cnt+1 > p->sz){
    int const n = p->cnt+7;
    fsl__bisect_qe * const a = fsl_realloc(p->a, sizeof(*a)*n);
    if(!a) return FSL_RC_OOM;
    p->a = a;
    p->sz = n;
  }
  p->a[p->cnt].node = node;
  p->a[p->cnt].value = v;
  i = p->cnt++;
  while((j = (i-1)/2)>=0 && p->a[j].value > p->a[i].value){
    fsl__bisect_qe const t = p->a[j];
    p->a[j] = p->a[i];
    p->a[i] = t;
    i = j;
  }
  return 0;
}

static fsl_vpath_node * fsl__bisect_pq_extract(fsl__bisect_pq * const p,
                                               double * v){
  fsl_vpath_node * node;
  int i, j;
  if(0==p->cnt) return NULL;
  node = p->a[0].node;
  *v = p->a[0].value;
  i = 0;
  p->a[0] = p->a[p->cnt-1];
  p->cnt--;
  while((j = i*2+1) < p->cnt){
    if(j+1 < p->cnt && p->a[j].value > p->a[j+1].value) j++;
    if(p->a[i].value < p->a[j].value) break;
    fsl__bisect_qe const t = p->a[i];
    p->a[i] = p->a[j];
    p->a[j] = t;
    i = j;
  }
  return node;
}

/** Adds a node to path's list of all nodes, which fsl_vpath_clear()
    frees. */
static fsl_vpath_node * fsl__bisect_new_node(fsl_vpath * const path,
                                             fsl_id_t rid,
                                             fsl_vpath_node * pFrom,
                                             bool isParent,
                                             fsl_id_bag const * hidden){
  fsl_vpath_node * const p = fsl_malloc(sizeof(*p));
  if(!p) return NULL;
  memset(p, 0, sizeof(*p));
  p->rid = rid;
  p->fromIsParent = isParent;
  p->pFrom = pFrom;
  p->isHidden = hidden && fsl_id_bag_contains(hidden, rid);
  p->pAll = path->pAll;
  path->pAll = p;
  return p;
}

static int fsl__bisect_shortest(fsl_cx * const f, fsl_vpath * const path,
                                fsl_id_t iFrom, fsl_id_t iTo,
                                bool directOnly,
                                fsl_id_bag const * hidden){
  fsl__bisect_pq pq = {NULL, 0, 0};
  fsl_stmt s = fsl_stmt_empty;
  fsl_vpath_node * p;
  double cost = 0;
  int rc;
  fsl_vpath_clear(path);
  path->pStart = fsl__bisect_new_node(path, iFrom, NULL, false, NULL);
  if(!path->pStart) return FSL_RC_OOM;
  if(iTo==iFrom){
    path->pEnd = path->pStart;
    path->pEnd->u.pTo = NULL;
    return 0;
  }
  rc = fsl__bisect_pq_insert(&pq, path->pStart, 1.0);
  if(!rc) rc = fsl_cx_prepare(f, &s, directOnly
    ? "SELECT cid, 1 FROM {{dbname.repo}}.plink WHERE pid=?1 AND isprim"
      " UNION ALL"
      " SELECT pid, 0 FROM {{dbname.repo}}.plink WHERE ?2 AND cid=?1 AND isprim"
    : "SELECT cid, 1 FROM {{dbname.repo}}.plink WHERE pid=?1"
      " UNION ALL"
      " SELECT pid, 0 FROM {{dbname.repo}}.plink WHERE ?2 AND cid=?1");
  while(!rc && (p = fsl__bisect_pq_extract(&pq, &cost))){
    if(p->rid==iTo){
      fsl_vpath_node * q;
      path->pEnd = p;
      for(q = path->pEnd; q && q->pFrom; q = q->pFrom){
        q->pFrom->u.pTo = q;
        ++path->nStep;
      }
      path->pEnd->u.pTo = NULL;
      goto end;
    }
    if(fsl_id_bag_contains(&path->seen, p->rid)) continue;
    rc = fsl_id_bag_insert(&path->seen, p->rid);
    if( !rc ){
      rc = fsl_stmt_bind_fmt(&s, "Ri", p->rid,
                             (int)(p->fromIsParent ? 0 : 1))
        /* Only go back to a parent if this node was not reached from
           its parent: no zig-zags. */;
      if( rc ){
        rc = fsl_cx_uplift_db_error2(f, s.db, rc);
      }
    }
    while(!rc && fsl__cx_stmt_step_each(f, &s, &rc)){
      fsl_id_t const cid = fsl_stmt_g_id(&s, 0);
      fsl_vpath_node * pNew;
      if(fsl_id_bag_contains(&path->seen, cid)) continue;
      pNew = fsl__bisect_new_node(path, cid, p, !!fsl_stmt_g_int32(&s, 1),
                                  hidden);
      rc = pNew ? fsl__bisect_pq_insert(&pq, pNew, cost + 1.0)
        : FSL_RC_OOM;
    }
    fsl_stmt_reset(&s);
  }
  if(!rc) rc = FSL_RC_NOT_FOUND;
  end:
  fsl_stmt_finalize(&s);
  fsl_free(pq.a);
  if(rc) fsl_vpath_clear(path);
  return rc;
}

/** The number of non-hidden steps in path, as path.nNotHidden. */
static int fsl__bisect_not_hidden(fsl_vpath * const path){
  int n = 0;
  if(path->pStart && path->pStart!=path->pEnd){
    for(fsl_vpath_node * p = path->pStart->u.pTo; p; p = p->u.pTo){
      if(!p->isHidden) ++n;
    }
  }
  return n;
}

/** fossil(1)'s path_midpoint(). */
static fsl_vpath_node * fsl__bisect_midpoint(fsl_vpath * const path){
  int const nNotHidden = fsl__bisect_not_hidden(path);
  fsl_vpath_node * p;
  int i;
  if(nNotHidden<2) return NULL;
  for(p = path->pEnd, i = 0; p && (p->isHidden || i<nNotHidden/2);
      p = p->pFrom){
    if(!p->isHidden) ++i;
  }
  return p;
}

int fsl_bisect_path(fsl_cx * const f, fsl_vpath * const path){
  fsl_bisect_state_t st = fsl_bisect_state_t_empty;
  fsl_id_bag skip = fsl_id_bag_empty;
  char * zLog;
  int rc = fsl_bisect_state(f, &st);
  if(rc) return rc;
  if(st.good>0 && st.bad<=0){
    return fsl__bisect_shortest(f, path, st.good, st.good, false, NULL);
  }else if(st.bad>0 && st.good<=0){
    return fsl__bisect_shortest(f, path, st.bad, st.bad, false, NULL);
  }else if(st.good<=0 && st.bad<=0){
    return fsl_cx_err_set(f, FSL_RC_MISUSE, "Neither \"good\" nor \"bad\" "
                          "versions have been identified.");
  }
  zLog = fsl__bisect_vvar(f, "bisect-log");
  for(char const * z = zLog ? zLog : ""; !rc && *z; ){
    while(*z==' ') ++z;
    if(*z=='s'){
      fsl_id_t const rid = (fsl_id_t)strtoll(z+1, NULL, 10);
      if(rid>0) rc = fsl_id_bag_insert(&skip, rid);
    }
    while(*z && *z!=' ') ++z;
  }
  fsl_free(zLog);
  if(!rc){
    rc = fsl__bisect_shortest(f, path, st.good, st.bad,
                              fsl_bisect_option_is_on(f, "direct-only"),
                              &skip);
    if(FSL_RC_NOT_FOUND==rc){
      rc = fsl_cx_err_set(f, rc, "No path from good (%" FSL_ID_T_PFMT
                          ") to bad (%" FSL_ID_T_PFMT ") or back.",
                          st.good, st.bad);
    }
  }
  fsl_id_bag_clear(&skip);
  return rc;
}

int fsl_bisect_next(fsl_cx * const f, fsl_ckup_opt const * uOpt,
                    fsl_bisect_state_t * st){
  fsl_vpath path = fsl_vpath_empty;
  fsl_bisect_state_t s = fsl_bisect_state_t_empty;
  fsl_vpath_node * pMid;
  int rc = fsl_bisect_path(f, &path);
  if(rc) return rc;
  fsl_bisect_state(f, &s);
  if(fsl_bisect_option_is_on(f, "linear")){
    /* fossil(1)'s path_next(), unless that is where the checkout is. */
    pMid = path.pStart ? path.pStart->u.pTo : NULL;
    if(pMid && pMid->rid==f->db.ckout.rid) pMid = NULL;
  }else{
    pMid = fsl__bisect_midpoint(&path);
  }
  s.span = fsl__bisect_not_hidden(&path);
  for(int j = 1; j < s.span; j += j) ++s.stepsLeft;
  /* bisect-complete stays set once set, as in fossil(1) (e.g. after
     an undo of the last verdict), but this step reports its own
     result. */
  s.complete = !pMid;
  if(!pMid){
    rc = fsl__bisect_vvar_set_id(f, "bisect-complete", 1);
  }else{
    s.next = pMid->rid;
    if(uOpt){
      fsl_ckup_opt o = *uOpt;
      o.checkinRid = pMid->rid;
      rc = fsl_ckout_update(f, &o);
    }
  }
  fsl_vpath_clear(&path);
  if(!rc && st) *st = s;
  return rc;
}
