int fsl__dir_list(char const * zDir,
                  int (*cb)(void * cbState, char const * zEntry),
                  void * cbState){
  /* As fsl_dircrawl_impl() reads a directory, for one level. */
  int rc = 0;
  struct dirent * dent;
  DIR * const dir = opendir(zDir);
  if(!dir) return fsl_errno_to_rc(errno, FSL_RC_IO);
  while(!rc && (dent = readdir(dir))){
    char const * z = dent->d_name;
    char * zUtf8;
    if('.'==*z && (!z[1] || ('.'==z[1] && !z[2]))) continue;
    zUtf8 = fsl__dirent_utf8(z);
    if(!zUtf8){
      rc = FSL_RC_OOM;
      break;
    }
    rc = cb(cbState, zUtf8);
    fsl__dirent_utf8_free(zUtf8);
  }
  closedir(dir);
  return rc;
}

#undef fsl__dirent_utf8
#undef fsl__dirent_utf8_free
#undef MARKER
#ifdef _WIN32
#  undef DIR
#  undef dirent
#  undef opendir
#  undef readdir
#  undef closedir
#endif
