bool fsl_looks_like_binary(fsl_b const * const b){
  return (fsl_looks_like_utf8(b, FSL_LOOKSLIKE_BINARY) & FSL_LOOKSLIKE_BINARY)
    != FSL_LOOKSLIKE_NONE;
}

int fsl_looks_like_utf8(fsl_b const * const b, int stopFlags){
  fsl_size_t n = 0;
  const char *z = fsl_b_cstr2(b, &n);
  int j, c, flags = FSL_LOOKSLIKE_NONE;  /* Assume UTF-8 text, prove otherwise */

  if( n==0 ) return flags;  /* Empty file -> text */
  c = *z;
  if( c==0 ){
    flags |= FSL_LOOKSLIKE_NUL;  /* NUL character in a file -> binary */
  }else if( c=='\r' ){
    flags |= FSL_LOOKSLIKE_CR;
    if( n<=1 || z[1]!='\n' ){
      flags |= FSL_LOOKSLIKE_LONE_CR;  /* Not enough chars or next char not LF */
    }
  }
  j = (c!='\n');
  if( !j ) flags |= (FSL_LOOKSLIKE_LF | FSL_LOOKSLIKE_LONE_LF);  /* Found LF as first char */
  while( !(flags&stopFlags) && --n>0 ){
    int c2 = c;
    c = *++z; ++j;
    if( c==0 ){
      flags |= FSL_LOOKSLIKE_NUL;  /* NUL character in a file -> binary */
    }else if( c=='\n' ){
      flags |= FSL_LOOKSLIKE_LF;
      if( c2=='\r' ){
        flags |= (FSL_LOOKSLIKE_CR | FSL_LOOKSLIKE_CRLF);  /* Found LF preceded by CR */
      }else{
        flags |= FSL_LOOKSLIKE_LONE_LF;
      }
      if( j>FSL__LINE_LENGTH_MASK ){
        flags |= FSL_LOOKSLIKE_LONG;  /* Very long line -> binary */
      }
      j = 0;
    }else if( c=='\r' ){
      flags |= FSL_LOOKSLIKE_CR;
      if( n<=1 || z[1]!='\n' ){
        flags |= FSL_LOOKSLIKE_LONE_CR;  /* Not enough chars or next char not LF */
      }
    }
  }
  if( n ){
    flags |= FSL_LOOKSLIKE_SHORT;  /* The whole blob was not examined */
  }
  if( j>FSL__LINE_LENGTH_MASK ){
    flags |= FSL_LOOKSLIKE_LONG;  /* Very long line -> binary */
  }
  return flags;
}

unsigned char const *fsl_utf8_bom(unsigned int *pnByte){
  static const unsigned char bom[] = {
    0xef, 0xbb, 0xbf, 0x00, 0x00, 0x00
  };
  if( pnByte ) *pnByte = 3;
  return bom;
}

bool fsl_starts_with_bom_utf8(fsl_b const * const b,
                              unsigned int *pBomSize){
  unsigned int bomSize;
  const char * const z = fsl_b_cstr(b);
  const unsigned char * const bom = fsl_utf8_bom(&bomSize);
  if( pBomSize ) *pBomSize = bomSize;
  return fsl_b_size(b)<bomSize
    ? false
    : memcmp(z, bom, bomSize)==0;
}

bool fsl_b_has_bom(fsl_b const * const b){
  unsigned char const * const z = b->mem;
  fsl_size_t const n = b->used;
  if(n>=3 && z[0]==0xef && z[1]==0xbb && z[2]==0xbf) return true;
  return n>=2 && ((z[0]==0xff && z[1]==0xfe) || (z[0]==0xfe && z[1]==0xff));
}

/** Appends the UTF-8 encoding of c to the n bytes at z, returning the
    new byte count. */
static fsl_size_t fsl__utf8_put(unsigned char * z, fsl_size_t n,
                                unsigned int c){
  if(c<0x80){
    z[n++] = (unsigned char)c;
  }else if(c<0x800){
    z[n++] = (unsigned char)(0xc0 | (c>>6));
    z[n++] = (unsigned char)(0x80 | (c&0x3f));
  }else if(c<0x10000){
    z[n++] = (unsigned char)(0xe0 | (c>>12));
    z[n++] = (unsigned char)(0x80 | ((c>>6)&0x3f));
    z[n++] = (unsigned char)(0x80 | (c&0x3f));
  }else{
    z[n++] = (unsigned char)(0xf0 | (c>>18));
    z[n++] = (unsigned char)(0x80 | ((c>>12)&0x3f));
    z[n++] = (unsigned char)(0x80 | ((c>>6)&0x3f));
    z[n++] = (unsigned char)(0x80 | (c&0x3f));
  }
  return n;
}

int fsl_b_to_utf8_no_bom(fsl_b * const b){
  unsigned char const * const z = b->mem;
  fsl_size_t const n = b->used;
  if(n>=3 && z[0]==0xef && z[1]==0xbb && z[2]==0xbf){
    memmove(b->mem, b->mem+3, n-3);
    b->used = n-3;
    b->mem[b->used] = 0;
    return 0;
  }
  if(n>=2 && ((z[0]==0xff && z[1]==0xfe) || (z[0]==0xfe && z[1]==0xff))){
    bool const le = z[0]==0xff;
    fsl_b out = fsl_b_empty;
    fsl_size_t i, nOut = 0;
    /* Each 2-byte unit becomes at most 3 bytes; a 4-byte pair, 4. */
    int const rc = fsl_b_reserve(&out, n/2*3 + 1);
    if(rc) return rc;
    for(i=2; i+1<n; i+=2){
      unsigned int c = le ? (z[i] | (z[i+1]<<8)) : ((z[i]<<8) | z[i+1]);
      if(c>=0xd800 && c<=0xdbff && i+3<n){
        unsigned int const c2 = le
          ? (z[i+2] | (z[i+3]<<8)) : ((z[i+2]<<8) | z[i+3]);
        if(c2>=0xdc00 && c2<=0xdfff){
          c = 0x10000 + ((c-0xd800)<<10) + (c2-0xdc00);
          i += 2;
        }else{
          c = 0xfffd;
        }
      }else if(c>=0xd800 && c<=0xdfff){
        c = 0xfffd;
      }
      nOut = fsl__utf8_put(out.mem, nOut, c);
    }
    out.used = nOut;
    out.mem[nOut] = 0;
    fsl_b_swap(b, &out);
    fsl_b_clear(&out);
  }
  return 0;
}

bool fsl_invalid_utf8(fsl_b const * const b){
  fsl_size_t n = 0;
  const unsigned char *z = (unsigned char *) fsl_b_cstr2(b, &n);
  unsigned char c; /* lead byte to be handled. */
  if( n==0 ) return false;  /* Empty file -> OK */
  c = *z;
  while( --n>0 ){
    if( c>=0x80 ){
      const unsigned char *def; /* pointer to range table*/
      c <<= 1; /* multiply by 2 and get rid of highest bit */
      def = &lb_tab[c]; /* search fb's valid range in table */
      if( (unsigned int)(*++z-def[0])>=def[1] ){
        return true/*FSL_LOOKSLIKE_INVALID*/;
      }
      c = (c>=0xC0) ? (c|3) : ' '; /* determine next lead byte */
    } else {
      c = *++z;
    }
  }
  return c>=0x80 /* Final lead byte must be ASCII. */;
}
