/* ===================================================================
   Native socket/TLS sync channel: fsl_sc_socket.

   Merged from the standalone src/sc-socket.c. A drop-in peer of
   fsl_sc_popen_curl for http:// and https:// which speaks HTTP over a
   TCP socket directly, removing the external curl dependency. The
   https:// path uses OpenSSL and is compiled in only with
   -DFSL_NATIVE_TLS_OPENSSL (linked with -lssl -lcrypto); without it,
   http:// works and https:// reports a clear error.

   This channel uses the library-generated HTTP request headers
   (FSL_SC_F_REQUEST_HEADERS), as the "fossil test-http" channel does:
   the library writes the full request line, headers, login cookie, and
   the terminating blank line into ch->requestHeaders. submit() emits
   those followed by the request body, and leaves the entire HTTP
   response (status line, headers, body) for the library to parse via
   read().
   =================================================================== */
#if defined(_WIN32)
#  error "Native channel targets POSIX; port the socket layer for Win32."
#else
#  include <poll.h>
#  include <arpa/inet.h>
#  include <netdb.h>
#  include <netinet/in.h>
#  include <netinet/tcp.h>
#  include <limits.h>
#  include <pthread.h>
#  include <signal.h>
#  include <sys/socket.h>
#  include <sys/time.h>
#  include <sys/types.h>
#endif
#if defined(FSL_NATIVE_TLS_OPENSSL)
#  include <openssl/ssl.h>
#  include <openssl/err.h>
#  include <openssl/evp.h>
#  include <openssl/x509.h>
#  include <openssl/x509v3.h>
#endif

/* Per-channel private state, hung off fsl_sc::impl.p. */
typedef struct fsl_sc_socket_state {
  int fd;                  /* connected socket, or -1 */
  bool tls;                /* https? */
  fsl_b out;          /* outbound request body, built via append() */
  fsl_b in;           /* inbound response: full HTTP reply */
  fsl_size_t inCursor;     /* read offset into `in` */
  bool responseLoaded;     /* submit() has populated `in` */
#if defined(FSL_NATIVE_TLS_OPENSSL)
  SSL_CTX * sslCtx;
  SSL * ssl;
#endif
} fsl_sc_socket_state;

/* impl.type marker for semi-typesafety, per the fsl_sc convention. */
static const int fsl_sc_socket_type_marker = 0;
#define SOCK_STATE(ch) \
  fsl_sc_socket_state * const st = (fsl_sc_socket_state*)(ch)->impl.p; \
  assert((ch)->impl.type == &fsl_sc_socket_type_marker)

/* Default seconds a read or write on the socket may make no progress. */
#define FSL__SC_SOCKET_TIMEOUT 120

/* Seconds a read or write may make no progress: the xfer config's
   socketTimeoutSeconds, else the default. */
static int fsl_sc_socket_timeout(fsl_sc const * const ch){
  return ch->xfer && ch->xfer->config
    && ch->xfer->config->socketTimeoutSeconds>0
    ? ch->xfer->config->socketTimeoutSeconds : FSL__SC_SOCKET_TIMEOUT;
}

/*
** Describes errno value e. The socket's SO_RCVTIMEO and SO_SNDTIMEO
** make a read or write which makes no progress fail with EAGAIN.
*/
static char const * fsl_sc_errno_str(int e){
  return (EAGAIN==e || EWOULDBLOCK==e) ? "timed out" : strerror(e);
}

/*
** True if host holds a byte outside ASCII. The channel does not
** convert an internationalised domain name to its ASCII form (IDNA),
** and neither does fossil(1).
*/
static bool fsl_sc_host_is_non_ascii(char const *host){
  for( ; *host; ++host ){
    if( (unsigned char)*host >= 0x80 ) return true;
  }
  return false;
}

/* ---- TLS layer (OpenSSL), compiled only when requested ---- */
#if defined(FSL_NATIVE_TLS_OPENSSL)
/*
** Writes the lower-case hex SHA-256 of cert to zOut
*/
static void fsl__sc_tls_fingerprint(X509 *cert, char *zOut){
  unsigned char md[EVP_MAX_MD_SIZE];
  unsigned int n = 0, i;
  if( !X509_digest(cert, EVP_sha256(), md, &n) ) n = 0;
  for( i=0; i<n; ++i ){
    zOut[i*2] = "0123456789abcdef"[md[i]>>4];
    zOut[i*2+1] = "0123456789abcdef"[md[i]&0xf];
  }
  zOut[n*2] = 0;
}

/*
** Returns setting zKey from the repository or, failing that, from the
** global config db, as fossil(1)'s db_get() does, or NULL. The global
** config db is opened if needed. A setting which cannot be read is
** treated as unset, so the caller falls back to its default.
*/
static char * fsl__sc_tls_setting(fsl_cx * const f, char const * zKey){
  char * z = fsl_cx_db_repo(f)
    ? fsl_config_get_text(f, FSL_CONFDB_REPO, zKey, NULL) : NULL;
  if( !z ){
    if( fsl_config_open(f, NULL) ) fsl_cx_err_reset(f);
    else z = fsl_config_get_text(f, FSL_CONFDB_GLOBAL, zKey, NULL);
  }
  return z;
}

/*
** Loads the trust store into ctx. When $SSL_CERT_FILE or $SSL_CERT_DIR
** is set, OpenSSL's default paths use it, as fossil(1) gives the
** environment first priority. Otherwise the ssl-ca-location setting
** is used when it refers to an existing file or directory, and
** OpenSSL's defaults when it does not.
*/
static int fsl__sc_tls_trust(fsl_cx * const f, SSL_CTX * ctx){
  char * zCa = NULL;
  int d = 0, ok;
  if( f && !getenv(X509_get_default_cert_file_env())
      && !getenv(X509_get_default_cert_dir_env()) ){
    zCa = fsl__sc_tls_setting(f, "ssl-ca-location");
    if( zCa ) d = fsl_dir_check(zCa);
  }
  if( d>0 ) ok = SSL_CTX_load_verify_locations(ctx, NULL, zCa);
  else if( d<0 ) ok = SSL_CTX_load_verify_locations(ctx, zCa, NULL);
  else ok = SSL_CTX_set_default_verify_paths(ctx);
  fsl_free(zCa);
  return ok;
}

/*
** Returns true if the cert:HOST setting holds zFp, the fingerprint of
** a certificate which failed verification. fossil(1) stores that
** setting when its user accepts such a certificate and asks for the
** exception to be remembered.
*/
static bool fsl__sc_tls_exception(fsl_cx * const f, char const *host,
                                  char const *zFp){
  char * zKey;
  char * zVal = NULL;
  bool rv;
  if( !f || !*zFp ) return false;
  zKey = fsl_mprintf("cert:%s", host);
  if( !zKey ) return false;
  for( char * z = zKey + 5; *z; ++z ){
    if( *z>='A' && *z<='Z' ) *z += 'a' - 'A';
  }
  zVal = fsl__sc_tls_setting(f, zKey);
  rv = zVal && 0==fsl_strcmp(zVal, zFp);
  fsl_free(zVal);
  fsl_free(zKey);
  return rv;
}

/*
** Sets the name the server's certificate must match: an IP address
** is matched against the certificate's IP addresses, any other host
** against its DNS names.
*/
static int fsl__sc_tls_host(SSL *ssl, char const *host){
  if( X509_VERIFY_PARAM_set1_ip_asc(SSL_get0_param(ssl), host) ){
    return 0;
  }
  ERR_clear_error();
#if OPENSSL_VERSION_MAJOR >= 4
  /* OpenSSL 4 deprecates SSL_set1_host() in favour of this. */
  return SSL_set1_dnsname(ssl, host) ? 0 : FSL_RC_IO;
#else
  return SSL_set1_host(ssl, host) ? 0 : FSL_RC_IO;
#endif
}

/*
** True if host is an IP address. RFC 6066 permits only a DNS name in
** the TLS server name indication.
*/
static bool fsl__sc_tls_host_is_ip(char const *host){
  struct in_addr a4;
  struct in6_addr a6;
  return 1==inet_pton(AF_INET, host, &a4)
    || 1==inet_pton(AF_INET6, host, &a6);
}

/*
** Performs the TLS handshake on st->fd and verifies the server's
** certificate chain against the trust store, and its name against
** host. A certificate which fails verification is accepted when
** fossil(1) has a remembered exception for it. f, which may be NULL,
** supplies the settings. If verify is false, as for
** FSL_SC_F_TLS_ACCEPT_ANY_CERT, any certificate is accepted. An IPv6
** address in host has no brackets.
**
** On failure, writes a description of the failure to zErr. A failed
** verification returns FSL_RC_ACCESS and describes OpenSSL's reason
** and the certificate's SHA-256 fingerprint. Any other failure
** returns FSL_RC_IO and takes its description from OpenSSL's error
** queue or from errno.
*/
static int fsl_sc_tls_handshake(fsl_cx * const f, fsl_sc_socket_state *st,
                                char const *host, bool verify,
                                char *zErr, size_t nErr){
  SSL_CTX * ctx;
  SSL * ssl = NULL;
  X509 * cert;
  long vrc;
  int sslRc;
  int rc = FSL_RC_IO;
  char zFp[EVP_MAX_MD_SIZE*2+1];
  char zDotless[256];
  char const * zTlsName = host;  /* host as the TLS layer needs it */
  {
    /* A fully qualified name may end with a dot, as in
       "example.com.". Strip it before being put into TLS server names
       (RFC 6066) or certificate names. */
    fsl_size_t const n = fsl_strlen(host);
    if( n>1 && '.'==host[n-1] && n<sizeof(zDotless) ){
      memcpy(zDotless, host, n-1);
      zDotless[n-1] = 0;
      zTlsName = zDotless;
    }
  }
  SSL_library_init();
  ERR_clear_error();
  zErr[0] = 0;
  ctx = SSL_CTX_new(TLS_client_method());
  if( !ctx ) goto err;
  if( verify && !fsl__sc_tls_trust(f, ctx) ) goto err;
  ssl = SSL_new(ctx);
  if( !ssl ) goto err;
  SSL_set_fd(ssl, st->fd);
#ifdef SSL_set_tlsext_host_name
  /* The server name must be an ASCII DNS name (RFC 6066). */
  if( !fsl__sc_tls_host_is_ip(zTlsName)
      && !fsl_sc_host_is_non_ascii(zTlsName) ){
    SSL_set_tlsext_host_name(ssl, zTlsName);
  }
#endif
  if( verify && fsl__sc_tls_host(ssl, zTlsName) ) goto err;
  errno = 0;
  if( (sslRc = SSL_connect(ssl))!=1 ){
    int const e = SSL_get_error(ssl, sslRc);
    if( SSL_ERROR_SYSCALL==e && !ERR_peek_error() ){
      fsl_snprintf(zErr, (fsl_size_t)nErr, "%s",
                   errno ? fsl_sc_errno_str(errno)
                   : "connection closed by peer");
    }
    goto err;
  }
  rc = FSL_RC_ACCESS;
  cert = SSL_get_peer_certificate(ssl);
  if( !cert ){
    fsl_snprintf(zErr, (fsl_size_t)nErr, "no certificate presented");
    goto err;
  }
  vrc = verify ? SSL_get_verify_result(ssl) : X509_V_OK;
  if( X509_V_OK!=vrc ){
    fsl__sc_tls_fingerprint(cert, zFp);
    if( !fsl__sc_tls_exception(f, host, zFp) ){
      fsl_snprintf(zErr, (fsl_size_t)nErr, "%s (sha256 %s)",
                   X509_verify_cert_error_string(vrc), zFp);
    }
  }
  X509_free(cert);
  if( zErr[0] ) goto err;
  st->sslCtx = ctx; st->ssl = ssl;
  return 0;
err:
  if( !zErr[0] ){
    unsigned long const e = ERR_peek_last_error();
    if( e ) ERR_error_string_n(e, zErr, nErr);
    else fsl_snprintf(zErr, (fsl_size_t)nErr, "no detail from OpenSSL");
  }
  ERR_clear_error();
  if( ssl ) SSL_free(ssl);
  if( ctx ) SSL_CTX_free(ctx);
  return rc;
}
/*
** Interprets rc, the non-positive result of SSL_read() or
** SSL_write(). Returns 0 at the end of the stream, including a peer
** which closes the connection without TLS's close_notify alert, which
** many servers do: the HTTP layer checks the body against its
** Content-Length. Otherwise returns -1, and either leaves errno set
** by the failed system call, or describes OpenSSL's reason in zErr.
** A read or write which timed out leaves errno set to EAGAIN.
*/
static fsl_int_t fsl_sc_tls_result(fsl_sc_socket_state *st, int rc,
                                   char *zErr, size_t nErr){
  int const sysErr = errno;
  int const e = SSL_get_error(st->ssl, rc);
  unsigned long const ee = ERR_peek_error();
  if( SSL_ERROR_ZERO_RETURN==e ) return 0;
  if( SSL_ERROR_WANT_READ==e || SSL_ERROR_WANT_WRITE==e ){
    /* The blocking socket's SO_RCVTIMEO or SO_SNDTIMEO expired. */
    errno = sysErr ? sysErr : EAGAIN;
    return -1;
  }
  if( SSL_ERROR_SYSCALL==e && !ee ){
    errno = sysErr;
    return sysErr ? -1 : 0;
  }
#ifdef SSL_R_UNEXPECTED_EOF_WHILE_READING
  if( SSL_ERROR_SSL==e
      && SSL_R_UNEXPECTED_EOF_WHILE_READING==ERR_GET_REASON(ee) ){
    ERR_clear_error();
    return 0;
  }
#endif
  if( ee ) ERR_error_string_n(ERR_peek_last_error(), zErr, nErr);
  else fsl_snprintf(zErr, (fsl_size_t)nErr, "SSL error %d", e);
  ERR_clear_error();
  errno = 0;
  return -1;
}
static fsl_int_t fsl_sc_tls_write(fsl_sc_socket_state *st,
                                  void const *p, fsl_size_t n,
                                  char *zErr, size_t nErr){
  int rc;
  zErr[0] = 0;
  ERR_clear_error();
  errno = 0;
  rc = SSL_write(st->ssl, p, n>(fsl_size_t)INT_MAX ? INT_MAX : (int)n);
  return rc>0 ? (fsl_int_t)rc : fsl_sc_tls_result(st, rc, zErr, nErr);
}
static fsl_int_t fsl_sc_tls_read(fsl_sc_socket_state *st,
                                 void *p, fsl_size_t n,
                                 char *zErr, size_t nErr){
  int rc;
  zErr[0] = 0;
  ERR_clear_error();
  errno = 0;
  rc = SSL_read(st->ssl, p, n>(fsl_size_t)INT_MAX ? INT_MAX : (int)n);
  return rc>0 ? (fsl_int_t)rc : fsl_sc_tls_result(st, rc, zErr, nErr);
}
static void fsl_sc_tls_close(fsl_sc_socket_state *st){
  if( st->ssl ){ SSL_shutdown(st->ssl); SSL_free(st->ssl); st->ssl=0; }
  if( st->sslCtx ){ SSL_CTX_free(st->sslCtx); st->sslCtx=0; }
}
#endif /* FSL_NATIVE_TLS_OPENSSL */

/*
** Writing to a socket whose peer has closed it raises SIGPIPE, which
** kills the process by default. OpenSSL writes with write(2), so
** MSG_NOSIGNAL cannot help it. The library leaves the process's signal
** dispositions alone: it blocks SIGPIPE in the calling thread while it
** uses the socket, so that a write fails with EPIPE, and on restoring
** the mask discards a SIGPIPE which became pending in the meantime.
*/
typedef struct {
  sigset_t old;     /* signal mask to restore */
  bool wasPending;  /* SIGPIPE was already pending before blocking */
} fsl_sc_sigpipe_state;

static void fsl_sc_sigpipe_block(fsl_sc_sigpipe_state *s){
  sigset_t set, pending;
  sigemptyset(&set);
  sigaddset(&set, SIGPIPE);
  pthread_sigmask(SIG_BLOCK, &set, &s->old);
  sigpending(&pending);
  s->wasPending = 1==sigismember(&pending, SIGPIPE);
}

static void fsl_sc_sigpipe_restore(fsl_sc_sigpipe_state const *s){
  sigset_t pending;
  int const savedErrno = errno;
  sigpending(&pending);
  if( !s->wasPending && 1==sigismember(&pending, SIGPIPE) ){
    sigset_t set;
    int sig = 0;
    sigemptyset(&set);
    sigaddset(&set, SIGPIPE);
    sigwait(&set, &sig);
  }
  pthread_sigmask(SIG_SETMASK, &s->old, NULL);
  errno = savedErrno;
}

/*
** Open a TCP connection to host:port, set TCP_NODELAY, and (for https)
** perform the TLS handshake.
*/
static int fsl_sc_socket_connect(fsl_sc *ch){
  SOCK_STATE(ch);
  fsl_sc * const self = ch->self(ch);
  fsl_url const * const url = &self->url;
  char zPort[16];
  char zHost[64];
  char const * zAddr = url->host;
  struct addrinfo hints, *ai = 0, *p = 0;
  int gai;
  int lastErrno = 0;

  if( st->fd >= 0 ) return 0; /* already connected */
  fsl_snprintf(zPort, sizeof(zPort), "%d",
               (int)(url->port ? url->port : (st->tls ? 443 : 80)));
  memset(&hints, 0, sizeof(hints));
  hints.ai_family = AF_UNSPEC;
  hints.ai_socktype = SOCK_STREAM;
  hints.ai_protocol = IPPROTO_TCP;
  if( '['==url->host[0] ){
    /* fsl_url_parse() keeps an IP literal's brackets, which
       getaddrinfo() and the TLS layer do not accept. */
    fsl_size_t const n = fsl_strlen(url->host);
    if( n<3 || n-2>=sizeof(zHost) ){
      return fsl_xfer_errorf(ch->xfer, FSL_RC_RANGE,
                             "Invalid IP literal host: %s", url->host);
    }
    memcpy(zHost, url->host+1, n-2);
    zHost[n-2] = 0;
    zAddr = zHost;
  }
  gai = getaddrinfo(zAddr, zPort, &hints, &ai);
  if( gai!=0 ){
    return fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                           "getaddrinfo(%s:%s) failed: %s%s",
                           url->host, zPort, gai_strerror(gai),
                           fsl_sc_host_is_non_ascii(url->host)
                           ? " (give an internationalised domain name"
                             " in its ASCII xn-- form)"
                           : "");
  }
  for( p=ai; p; p=p->ai_next ){
    int fd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
    if( fd<0 ){ lastErrno = errno; continue; }
    if( connect(fd, p->ai_addr, p->ai_addrlen)<0 ){
      lastErrno = errno;
      close(fd);
      continue;
    }
    { int on = 1; setsockopt(fd, IPPROTO_TCP, TCP_NODELAY,
                             (void*)&on, sizeof(on)); }
    {
      /* Bounds every read and write, including the TLS handshake
         and the TLS reads, which do not poll(). */
      struct timeval tv;
      tv.tv_sec = fsl_sc_socket_timeout(ch);
      tv.tv_usec = 0;
      setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, (void*)&tv, sizeof(tv));
      setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, (void*)&tv, sizeof(tv));
    }
    st->fd = fd;
    break;
  }
  freeaddrinfo(ai);
  if( st->fd<0 ){
    return fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                           "Could not connect to %s:%s: %s", url->host,
                           zPort, lastErrno
                           ? strerror(lastErrno) : "no usable address");
  }
  if( st->tls ){
#if defined(FSL_NATIVE_TLS_OPENSSL)
    char zErr[256];
    int const rc = fsl_sc_tls_handshake(
      ch->xfer ? fsl_xfer_cx(ch->xfer) : NULL, st, zAddr,
      0==(self->flags & FSL_SC_F_TLS_ACCEPT_ANY_CERT),
      zErr, sizeof(zErr));
    if( rc ){
      /* Else a later submit() would find the socket connected and
         write to it with no TLS session. */
      close(st->fd);
      st->fd = -1;
    }
    if( FSL_RC_ACCESS==rc ){
      return fsl_xfer_errorf(ch->xfer, rc,
                             "Unable to verify SSL cert from %s: %s",
                             url->host, zErr);
    }else if( rc ){
      return fsl_xfer_errorf(ch->xfer, rc,
                             "TLS handshake with %s:%s failed: %s",
                             url->host, zPort, zErr);
    }
#else
    close(st->fd);
    st->fd = -1;
    return fsl_xfer_error(ch->xfer, FSL_RC_MISUSE,
                          "https requires building with FSL_NATIVE_TLS_OPENSSL.");
#endif
  }
  return 0;
}

/* Write n bytes, looping over partial writes; EINTR retried. */
static int fsl_sc_socket_write_all(fsl_sc *ch, void const *p, fsl_size_t n){
  SOCK_STATE(ch);
  char const *z = (char const *)p;
  char zErr[256];
  while( n>0 ){
    fsl_int_t got;
    zErr[0] = 0;
    if( st->tls ){
#if defined(FSL_NATIVE_TLS_OPENSSL)
      got = fsl_sc_tls_write(st, z, n, zErr, sizeof(zErr));
#else
      got = -1;
      errno = 0;
      fsl_snprintf(zErr, sizeof(zErr), "TLS write failed");
#endif
    }else{
      got = (fsl_int_t)send(st->fd, z, (size_t)n, 0);
    }
    if( got<0 && errno==EINTR ) continue;
    if( got<=0 ){
      fsl_url const * const url = &ch->self(ch)->url;
      return fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                             "Short write to socket for %s: %s",
                             url->host,
                             0==got ? "connection closed"
                             : (zErr[0] ? zErr
                                : fsl_sc_errno_str(errno)));
    }
    z += got; n -= (fsl_size_t)got;
  }
  return 0;
}

/*
** Read the whole HTTP response into st->in (cursor at 0), leaving the
** status line, headers, and body intact for the library to parse. A
** bounded poll() keeps a silent peer from wedging the sync. Reads until
** the peer closes the connection (HTTP/1.0 close-delimited).
*/
/*
** If the slurped response declares Transfer-Encoding: chunked, rewrite
** st->in so its body is de-chunked, leaving the status line and headers
** intact for the library's HTTP parser (which reads the body until EOF
** on the uncompressed clone path). A no-op otherwise, so close-delimited
** and Content-Length responses are untouched. HTTP/1.1 servers may send
** chunked even when "Connection: close" was requested, so this must be
** handled for the 1.1 upgrade to be correct.
*/
static int fsl_sc_socket_dechunk_if_needed(fsl_sc *ch){
  SOCK_STATE(ch);
  unsigned char * const m = (unsigned char*)st->in.mem;
  fsl_size_t const n = st->in.used;

  if( !m || n<4 ) return 0;

  fsl_size_t i, hdrEnd = 0, p, hdrStart = 0;
  bool chunked = false;
  bool haveContentLength = false;
  bool haveTransferEncoding = false;
  bool lengthOk = false;     /* each Content-Length parsed, all equal */
  fsl_size_t contentLength = 0;
  /* ch->xfer is NULL for raw/test-tool use of this channel (e.g.
  ** f-sync test-httpmsg before it wires one in) -- see the ch->xfer
  ** guards throughout this function's error paths below, which exist
  ** for exactly that case. Without a live fsl_xfer there is no
  ** fsl_cx to borrow pooled buffers from, so fall back to plain,
  ** unpooled ones instead of asserting this can't happen. */
  fsl_cx * const f = ch->xfer ? fsl_xfer_cx(ch->xfer) : NULL;
  int rc = 0;
  fsl_b outLocal = fsl_b_empty;
  fsl_b bodyLocal = fsl_b_empty;
  fsl_b *out = NULL;
  fsl_b *body = NULL;
  for(;;){
    /* Find the header block of the final reply, skipping empty lines
       and interim (1xx) replies before it, as the HTTP parser in
       xfer.c does. */
    while( hdrStart+1<n && m[hdrStart]=='\r' && m[hdrStart+1]=='\n' ){
      hdrStart += 2;
    }
    hdrEnd = 0;
    for( i=hdrStart; i+3 < n; ++i ){
      if( m[i]=='\r'&&m[i+1]=='\n'&&m[i+2]=='\r'&&m[i+3]=='\n' ){
        hdrEnd = i+4; break;
      }
    }
    if( 0==hdrEnd ) goto end; /* no header terminator; leave as-is */
    if( hdrEnd-hdrStart>9 && 0==memcmp(m+hdrStart, "HTTP/1.", 7)
        && ' '==m[hdrStart+8] && '1'==m[hdrStart+9] ){
      hdrStart = hdrEnd;
      continue;
    }
    break;
  }
  for( i=hdrStart; i < hdrEnd; ){
    fsl_size_t j = i, k;
    while( j<hdrEnd && m[j]!='\n' ) ++j;
    if( j<hdrEnd ) ++j;
    if( 0==fsl_strnicmp((char const*)m+i, "content-length:", 15) ){
      fsl_size_t v = 0;
      bool any = false;
      for( k=i+15; k<j && (m[k]==' ' || m[k]=='\t'); ++k ){}
      for( ; k<j && m[k]>='0' && m[k]<='9'; ++k ){
        unsigned const d = (unsigned)(m[k] - '0');
        if( v > (((fsl_size_t)-1) - d) / 10u ){ any = false; break; }
        v = v*10u + d;
        any = true;
      }
      /* xfer.c accepts a repeated value, and reports a malformed value
         or two different ones. */
      lengthOk = any && (!haveContentLength
                         || (lengthOk && v==contentLength));
      haveContentLength = true;
      contentLength = v;
    }else if( 0==fsl_strnicmp((char const*)m+i, "transfer-encoding:", 18) ){
      bool bOk = false;
      if( haveTransferEncoding ){
        rc = ch->xfer
          ? fsl_xfer_error(ch->xfer, FSL_RC_IO,
                           "Reply has repeated Transfer-Encoding headers.")
          : FSL_RC_IO;
        goto end;
      }
      haveTransferEncoding = true;
      for( k=i+18; k<j && (m[k]==' ' || m[k]=='\t'); ++k ){}
      if( k+7<=j && 0==fsl_strnicmp((char const*)m+k, "chunked", 7) ){
        k += 7;
        while( k<j && (m[k]==' ' || m[k]=='\t' || m[k]=='\r') ) ++k;
        bOk = k==j-1;
      }
      if( !bOk ){
        rc = ch->xfer
          ? fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                            "Unsupported transfer-encoding: %.*s",
                            (int)(j-i), (char const*)m+i)
          : FSL_RC_IO;
        goto end;
      }
      chunked = true;
    }
    i = j;
  }
  if( !chunked ){
    /* The reply ends after Content-Length bytes of body (RFC 9112
       section 6.3). Anything the peer sends after them, such as a
       second reply, is dropped, as fossil(1) drops it. A shorter
       body is left for the HTTP parser to report. */
    if( lengthOk && n-hdrEnd > contentLength ){
      st->in.used = hdrEnd + contentLength;
    }
    goto end;
  }
  if( haveContentLength ){
    rc = ch->xfer
      ? fsl_xfer_error(ch->xfer, FSL_RC_IO,
                       "Reply has both Content-Length and "
                       "Transfer-Encoding.")
      : FSL_RC_IO;
    goto end;
  }

  out = f ? fsl_cx_b_borrow(f) : &outLocal;
  body = f ? fsl_cx_b_borrow(f) : &bodyLocal;
  if( !out || !body ){
    assert( f );
    rc = f->error.code;
    goto end;
  }

  /* De-chunk the body into a scratch buffer first, since we need its
  ** length before we can write the Content-Length header. */
  p = hdrEnd;
  while( 0==rc ){
    fsl_size_t len = 0;
    bool any = false;
    if( p>=n ){
      if( ch->xfer ){
        rc = fsl_xfer_error(ch->xfer, FSL_RC_IO,
                            "Chunked response ended without terminator.");
      }else{
        rc = FSL_RC_IO;
      }
      break;
    }
    while( p<n && (m[p]==' ' || m[p]=='\t') ) ++p;
    while( p<n && m[p]!='\r' && m[p]!='\n' && m[p]!=';' ){
      int const c = m[p];
      int d;
      if( c>='0'&&c<='9' ) d = c-'0';
      else if( c>='a'&&c<='f' ) d = c-'a'+10;
      else if( c>='A'&&c<='F' ) d = c-'A'+10;
      else break;
      if( len > (((fsl_size_t)-1) - (fsl_size_t)d) / 16u ){
        if( ch->xfer ){
          rc = fsl_xfer_error(ch->xfer, FSL_RC_IO,
                              "Invalid chunked response size.");
        }else{
          rc = FSL_RC_IO;
        }
        break;
      }
      len = len*16u + (fsl_size_t)d; any = true; ++p;
    }
    if( rc ) break;
    if( !any ){
      if( ch->xfer ){
        rc = fsl_xfer_error(ch->xfer, FSL_RC_IO,
                            "Malformed chunked response size.");
      }else{
        rc = FSL_RC_IO;
      }
      break;
    }
    {
      /* After the size comes either the line end or, after optional
         spaces or tabs, ';' and an extension, which is ignored (RFC
         9112 section 7.1.1). Anything else means the size line is
         malformed. */
      fsl_size_t q = p;
      bool bad = false;
      while( q<n && (m[q]==' ' || m[q]=='\t') ) ++q;
      if( q<n && ';'==m[q] ){
        static char const zToken[] = "!#$%&'*+-.^_`|~";
        ++q;
        while( q<n && (m[q]==' ' || m[q]=='\t') ) ++q;
        bad = q>=n
          || !(fsl_isalnum(m[q]) || strchr(zToken, (char)m[q]));
      }else if( q<n && (q>p || (m[q]!='\r' && m[q]!='\n')) ){
        bad = true;
      }
      /* A CR is allowed only before the LF which ends the line (RFC
         9112 section 2.2), and a NUL nowhere in it. */
      for( q=p; !bad && q<n && '\n'!=m[q]; ++q ){
        bad = !m[q] || ('\r'==m[q] && q+1<n && '\n'!=m[q+1]);
      }
      if( bad ){
        if( ch->xfer ){
          rc = fsl_xfer_error(ch->xfer, FSL_RC_IO,
                              "Malformed chunked response size line.");
        }else{
          rc = FSL_RC_IO;
        }
        break;
      }
    }
    while( p<n && m[p]!='\n' ) ++p;  /* skip chunk extensions / CR */
    if( p>=n ){
      if( ch->xfer ){
        rc = fsl_xfer_error(ch->xfer, FSL_RC_IO,
                            "Truncated chunked response body.");
      }else{
        rc = FSL_RC_IO;
      }
      break;
    }
    ++p;                             /* consume the \n */
    if( 0==len ){
      bool trailerDone = false;
      /* Discard trailer headers, if any, but require their final empty
         line (RFC 9112 section 7.1). */
      while( p<n ){
        fsl_size_t const t = p;
        while( p<n && m[p]!='\n' ) ++p;
        if( p>=n ) break;
        ++p;
        if( (p-t)==1 || ((p-t)==2 && m[t]=='\r') ){
          trailerDone = true;
          break;
        }
      }
      if( !trailerDone ){
        rc = ch->xfer
          ? fsl_xfer_error(ch->xfer, FSL_RC_IO,
                           "Truncated chunked response trailer.")
          : FSL_RC_IO;
      }
      break;
    }
    if( len > n-p ){
      if( ch->xfer ){
        rc = fsl_xfer_error(ch->xfer, FSL_RC_IO,
                            "Truncated chunked response body.");
      }else{
        rc = FSL_RC_IO;
      }
      break;
    }
    rc = fsl_b_append(body, m+p, len);
    p += len;
    /* The chunk data ends with CRLF (RFC 9112 section 7.1). Any other
       byte there means the chunk size was wrong. */
    if( p<n && m[p]=='\r' ) ++p;
    if( 0==rc && (p>=n || m[p]!='\n') ){
      if( ch->xfer ){
        rc = fsl_xfer_error(ch->xfer, FSL_RC_IO,
                            "Malformed chunked response: no line end "
                            "after chunk data.");
      }else{
        rc = FSL_RC_IO;
      }
      break;
    }
    ++p;
  }
  if( rc ) goto end;

  /* Rebuild the header block: copy any interim replies before it as
  ** they are, then every header line except the transfer-encoding
  ** one, then add a Content-Length the parser wants. */
  if( hdrStart ) rc = fsl_b_append(out, m, hdrStart);
  i = hdrStart;
  while( 0==rc && i < hdrEnd ){
    fsl_size_t j = i;
    while( j<hdrEnd && m[j]!='\n' ) ++j;
    if( j<hdrEnd ) ++j;             /* include the \n */
    if( j-i==2 && m[i]=='\r' ) break; /* blank line ends the headers */
    if( 0!=fsl_strnicmp((char const*)m+i, "transfer-encoding:", 18) ){
      rc = fsl_b_append(out, m+i, j-i);
    }
    i = j;
  }
  if( 0==rc ){
    fsl_b_appendf(out, "Content-Length: %" FSL_SIZE_T_PFMT "\r\n\r\n",
                       body->used);
    rc = fsl_b_append(out, body->mem, body->used);
    if( 0==rc ){
      fsl_b_swap(&st->in, out);
    }
  }
end:
  if( f ){
    fsl_cx_b_return(f, body);
    fsl_cx_b_return(f, out);
  }else{
    fsl_b_clear(&bodyLocal);
    fsl_b_clear(&outLocal);
  }
  return rc;
}

static int fsl_sc_socket_slurp_response(fsl_sc *ch){
  SOCK_STATE(ch);
  char buf[16384];
  char zErr[256];
  int rc = 0;
  for(;;){
    fsl_int_t got = -1;
    bool timedOut = false;
    zErr[0] = 0;
    if( st->tls ){
#if defined(FSL_NATIVE_TLS_OPENSSL)
      got = fsl_sc_tls_read(st, buf, (fsl_size_t)sizeof(buf),
                            zErr, sizeof(zErr));
#else
      got = -1;
      errno = 0;
      fsl_snprintf(zErr, sizeof(zErr), "TLS read failed");
#endif
      if( got<0 && errno==EINTR ) continue;
      timedOut = got<0 && (EAGAIN==errno || EWOULDBLOCK==errno);
    }else{
      struct pollfd pfd;
      int nPoll;
      pfd.fd = st->fd; pfd.events = POLLIN;
      nPoll = poll(&pfd, 1, fsl_sc_socket_timeout(ch)*1000);
      if( nPoll<0 && errno==EINTR ) continue;
      if( nPoll<0 ){
        rc = fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                             "poll() on socket for %s failed: %s",
                             ch->self(ch)->url.host, strerror(errno));
        break;
      }
      timedOut = 0==nPoll;
      if( !timedOut ){
        got = (fsl_int_t)recv(st->fd, buf, sizeof(buf), 0);
        if( got<0 && errno==EINTR ) continue;
      }
    }
    if( timedOut ){
      if( st->in.used ){
        /* A peer which keeps the connection open after its reply. The
           HTTP parser checks the reply against its Content-Length. */
        break;
      }
      rc = fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                           "No response from %s within %d seconds",
                           ch->self(ch)->url.host,
                           fsl_sc_socket_timeout(ch));
      break;
    }
    if( got<0 ){
      rc = fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                           "Read error from socket for %s: %s",
                           ch->self(ch)->url.host,
                           zErr[0] ? zErr : strerror(errno));
      break;
    }
    if( got==0 ) break; /* peer closed: end of response */
    rc = fsl_b_append(&st->in, buf, (fsl_size_t)got);
    if( rc ) break;
  }
  /* The response was read close-delimited (HTTP/1.0): the peer has
     closed its side. Tear our side down too and reset st->fd so the
     next request (e.g. the next clone round-trip) opens a fresh
     connection instead of writing to a dead socket. The full response
     is already buffered in st->in, which read() serves from memory, so
     closing the socket here is safe. */
#if defined(FSL_NATIVE_TLS_OPENSSL)
  if( st->tls ) fsl_sc_tls_close(st);
#endif
  if( st->fd>=0 ){ close(st->fd); st->fd = -1; }
  if( 0==rc ) rc = fsl_sc_socket_dechunk_if_needed(ch);
  st->inCursor = 0;
  st->responseLoaded = true;
  return rc;
}

/* ---- fsl_sc vtable ---- */

static int fsl_sc_socket_xInit(fsl_sc *ch, enum fsl_sc_init_e mode){
  SOCK_STATE(ch);
  fsl_sc * const self = ch->self(ch);
  if( FSL_SC_INIT_INITIAL==mode ){
    char const * const scheme = self->url.scheme;
    if( !scheme
        || (0!=fsl_strcmp(scheme,"http") && 0!=fsl_strcmp(scheme,"https")) ){
      return fsl_xfer_errorf(ch->xfer, FSL_RC_MISUSE,
                             "Native channel requires http/https URL, "
                             "not %s.", scheme ? scheme : "(no scheme)");
    }
    st->tls = (0==fsl_strcmp(scheme,"https"));
    st->fd = -1;
  }
  if( FSL_SC_INIT_REQUEST==mode ){
    fsl_b_reuse(&st->out);
  }
  return 0;
}

static int fsl_sc_socket_xAppend(fsl_sc *ch, void const *pIn, fsl_size_t n){
  SOCK_STATE(ch);
  return fsl_b_append(&st->out, pIn, n);
}

/*
** Emit the library-generated request headers (which already include
** the request line, the login Cookie when authenticating, and the
** terminating blank line) followed by the request body, then read the
** entire response. loginCard is unused here: the library funnels the
** cookie into requestHeaders when FSL_SC_F_REQUEST_HEADERS is set,
** which this channel always sets. If a caller supplies headers that
** are not already blank-line-terminated (e.g. a hand-built request),
** the terminator is added so the request remains well-formed.
*/
static int fsl_sc_socket_submit(fsl_sc *ch, fsl_b const *loginCard){
  SOCK_STATE(ch);
  fsl_sc * const self = ch->self(ch);
  int rc;
  fsl_b_reuse(&st->in);
  st->inCursor = 0;
  st->responseLoaded = false;
  rc = fsl_sc_socket_connect(ch);
  (void)loginCard;
  if( rc ) return rc;

  if( self->requestHeaders.used ){
    fsl_b const * const h = &self->requestHeaders;
    /* Upgrade the library-generated "...HTTP/1.0\r\n" request line to
    ** HTTP/1.1, adding "Connection: close" so the peer still closes the
    ** connection after the response (preserving our close-delimited read
    ** model and avoiding keep-alive). Servers/proxies that reject HTTP/1.0
    ** then accept us. The rewrite is done on a local copy, so the
    ** library's buffer and the other channels are untouched. If the caller
    ** already supplied an HTTP/1.1 request line (e.g. the standalone
    ** channel test), no substitution occurs. */
    static char const v10[] = "HTTP/1.0\r\n";
    static char const v11[] = "HTTP/1.1\r\nConnection: close\r\n";
    char const * const z = (char const*)h->mem;
    fsl_size_t i, hit = (fsl_size_t)-1;
    for( i=0; i+10 <= h->used; ++i ){
      if( 0==memcmp(z+i, v10, 10) ){ hit = i; break; }
    }
    if( (fsl_size_t)-1 != hit ){
      /* ch->xfer is NULL for raw/test-tool use of this channel (e.g.
      ** the standalone channel test), same as in
      ** fsl_sc_socket_dechunk_if_needed() -- fall back to a plain,
      ** unpooled buffer rather than crash when there is no fsl_cx to
      ** borrow one from. This buffer is acquired lazily, only when a
      ** rewrite is actually needed, so the common already-1.1 case
      ** never touches it at all. */
      fsl_cx * const f = ch->xfer ? fsl_xfer_cx(ch->xfer) : NULL;
      fsl_b hbLocal = fsl_b_empty;
      fsl_b * const hb = f ? fsl_cx_b_borrow(f) : &hbLocal;
      if( !hb ){
        assert( f );
        return fsl_xfer_error(ch->xfer, f->error.code, 0);
      }
      fsl_b_append(hb, z, hit);
      fsl_b_append(hb, v11, (fsl_size_t)(sizeof(v11)-1));
      fsl_b_append(hb, z+hit+10, h->used-hit-10);
      rc = hb->errCode
        ? hb->errCode
        : fsl_sc_socket_write_all(ch, hb->mem, hb->used);
      if( f ){
        assert( hb != &hbLocal );
        fsl_cx_b_return(f, hb);
      }else{
        assert( hb == &hbLocal );
        fsl_b_clear(hb);
      }
    }else{
      rc = fsl_sc_socket_write_all(ch, h->mem, h->used);
    }
    if( rc ) return rc;
    /* Add a header terminator only if the caller did not already
    ** provide one (the library path always does). */
    if( h->used<4
        || 0!=memcmp((char const*)h->mem + h->used - 4, "\r\n\r\n", 4) ){
      rc = fsl_sc_socket_write_all(ch, "\r\n", 2);
      if( rc ) return rc;
    }
  }else{
    rc = fsl_sc_socket_write_all(ch, "\r\n", 2);
    if( rc ) return rc;
  }
  if( st->out.used ){
    rc = fsl_sc_socket_write_all(ch, st->out.mem, st->out.used);
    if( rc ) return rc;
  }
  return fsl_sc_socket_slurp_response(ch);
}

static int fsl_sc_socket_xSubmit(fsl_sc *ch, fsl_b const *loginCard){
  fsl_sc_sigpipe_state sp;
  int rc;
  fsl_sc_sigpipe_block(&sp);
  rc = fsl_sc_socket_submit(ch, loginCard);
  fsl_sc_sigpipe_restore(&sp);
  return rc;
}

static int fsl_sc_socket_xRead(fsl_sc *ch, fsl_b *tgt, fsl_int_t howMuch){
  SOCK_STATE(ch);
  fsl_size_t avail;
  unsigned char const * base;
  if( !st->responseLoaded ){
    return fsl_xfer_error(ch->xfer, FSL_RC_MISUSE,
                          "read() called before submit() loaded a response.");
  }
  avail = st->in.used - st->inCursor;
  base = (unsigned char const *)st->in.mem + st->inCursor;

  if( FSL_SC_READ_ALL==howMuch ){
    int rc = fsl_b_append(tgt, base, avail);
    st->inCursor = st->in.used;
    return rc;
  }
  if( FSL_SC_READ_LINE==howMuch ){
    fsl_size_t i = 0, take;
    int rc;
    if( 0==avail ) return FSL_RC_BREAK; /* clean EOF */
    while( i<avail && base[i]!='\n' ) ++i;
    take = (i<avail) ? (i+1) : avail; /* include newline if present */
    rc = fsl_b_append(tgt, base, take);
    if( rc ) return rc;
    st->inCursor += take;
    return 0;
  }
  /* howMuch > 0: deliver exactly that many bytes. */
  if( (fsl_size_t)howMuch > avail ){
    return fsl_xfer_errorf(ch->xfer, FSL_RC_IO,
                           "Short read: wanted %d, have %u.",
                           (int)howMuch, (unsigned)avail);
  }
  {
    int rc = fsl_b_append(tgt, base, (fsl_size_t)howMuch);
    if( rc ) return rc;
    st->inCursor += (fsl_size_t)howMuch;
    return 0;
  }
}

static void fsl_sc_socket_xCleanup(fsl_sc *ch){
  SOCK_STATE(ch);
  if( st ){
#if defined(FSL_NATIVE_TLS_OPENSSL)
    if( st->tls ){
      /* SSL_shutdown() writes the close_notify alert. */
      fsl_sc_sigpipe_state sp;
      fsl_sc_sigpipe_block(&sp);
      fsl_sc_tls_close(st);
      fsl_sc_sigpipe_restore(&sp);
    }
#endif
    if( st->fd>=0 ) close(st->fd);
    fsl_b_clear(&st->out);
    fsl_b_clear(&st->in);
    fsl_free(st);
    ch->impl.p = 0;
  }
}

const fsl_sc fsl_sc_socket = {
  .xfer = 0,
  .name = "http-socket",
  .url = fsl_url_empty_m,
  .flags = FSL_SC_F_REQUEST_HEADERS,
  .impl = { .p = 0, .type = &fsl_sc_socket_type_marker },
  .init = fsl_sc_socket_xInit,
  .append = fsl_sc_socket_xAppend,
  .submit = fsl_sc_socket_xSubmit,
  .read = fsl_sc_socket_xRead,
  .cleanup = fsl_sc_socket_xCleanup,
  .self = fsl_sc_self,
  .requestHeaders = fsl_b_empty_m,
  .scratch = fsl_b_empty_m
};

int fsl_sc_socket_state_init(fsl_sc *ch){
  fsl_sc_socket_state * st;
  assert( ch->impl.type == &fsl_sc_socket_type_marker );
  st = (fsl_sc_socket_state*)fsl_malloc(sizeof(fsl_sc_socket_state));
  if( !st ) return FSL_RC_OOM;
  memset(st, 0, sizeof(*st));
  st->fd = -1;
  st->out = fsl_b_empty;
  st->in = fsl_b_empty;
  ch->impl.p = st;
  return 0;
}

