/*************************************************************************
  This file implements ticket-related parts of the library.
*/
#include <assert.h>
#include <stdlib.h> /* bsearch() */
#include <string.h> /* memcmp() */

/* Length of the run of whitespace and SQL comments at z. */
static fsl_size_t fsl__tkt_sql_skip(char const * z){
  char const * const z0 = z;
  for(;;){
    if( fsl_isspace(*z) ) ++z;
    else if( '-'==z[0] && '-'==z[1] ){
      while( *z && '\n'!=*z ) ++z;
    }else if( '/'==z[0] && '*'==z[1] ){
      z += 2;
      while( *z && !('*'==z[0] && '/'==z[1]) ) ++z;
      if( *z ) z += 2;
    }else break;
  }
  return (fsl_size_t)(z - z0);
}

/* If z starts with keyword zKw (case-insensitive, then a non-word
   character), returns its length, else 0. */
static fsl_size_t fsl__tkt_sql_kw(char const * z, char const * zKw){
  fsl_size_t const n = fsl_strlen(zKw);
  return (0==fsl_strnicmp(z, zKw, n) && !fsl_isalnum(z[n]) && '_'!=z[n])
    ? n : 0;
}

/* Length of the (possibly quoted) identifier at z, or 0. */
static fsl_size_t fsl__tkt_sql_ident(char const * z){
  char const * const z0 = z;
  if( '"'==*z || '`'==*z || '['==*z ){
    char const q = ('['==*z) ? ']' : *z;
    for( ++z; *z && *z!=q; ++z ){}
    return *z ? (fsl_size_t)(z + 1 - z0) : 0;
  }
  while( fsl_isalnum(*z) || '_'==*z ) ++z;
  return (fsl_size_t)(z - z0);
}

int fsl__ticket_schema_qualify(fsl_db * const db, char const * zIn,
                               fsl_b * const out){
  char const * const zSchema = fsl__db_schema(db, FSL_DBROLE_REPO);
  char const * z = zIn;
  char const * zCopied = zIn;
  int rc = 0;
  while( 0==rc && *z ){
    char const c = *z;
    if( '\''==c || '"'==c || '`'==c || '['==c ){
      /* A string or quoted identifier: copy it as is. */
      char const q = ('['==c) ? ']' : c;
      for( ++z; *z; ++z ){
        if( *z==q ){
          if( '\''==q && '\''==z[1] ){ ++z; continue; }
          ++z;
          break;
        }
      }
      continue;
    }else if( ('-'==c && '-'==z[1]) || ('/'==c && '*'==z[1]) ){
      z += fsl__tkt_sql_skip(z);
      continue;
    }else if( (z==zIn || !(fsl_isalnum(z[-1]) || '_'==z[-1]))
              && fsl__tkt_sql_kw(z, "CREATE") ){
      /* CREATE [UNIQUE] TABLE|INDEX [IF NOT EXISTS] [schema.]name */
      char const * p = z + 6;
      fsl_size_t n;
      p += fsl__tkt_sql_skip(p);
      if( (n = fsl__tkt_sql_kw(p, "UNIQUE")) ) p += n + fsl__tkt_sql_skip(p + n);
      if( (n = fsl__tkt_sql_kw(p, "TABLE")) || (n = fsl__tkt_sql_kw(p, "INDEX")) ){
        p += n;
        p += fsl__tkt_sql_skip(p);
        if( (n = fsl__tkt_sql_kw(p, "IF")) ){
          char const * p2 = p + n;
          p2 += fsl__tkt_sql_skip(p2);
          if( (n = fsl__tkt_sql_kw(p2, "NOT")) ){
            p2 += n + fsl__tkt_sql_skip(p2 + n);
            if( (n = fsl__tkt_sql_kw(p2, "EXISTS")) ){
              p = p2 + n;
              p += fsl__tkt_sql_skip(p);
            }
          }
        }
        n = fsl__tkt_sql_ident(p);
        if( n ){
          char const * zName = p;
          fsl_size_t nName = n;
          if( '.'==p[n] ){
            /* A schema name: replaced by db's. */
            fsl_size_t const n2 = fsl__tkt_sql_ident(p + n + 1);
            if( n2 ){
              zName = p + n + 1;
              nName = n2;
            }
          }
          rc = fsl_b_append(out, zCopied, (fsl_int_t)(p - zCopied));
          if( 0==rc ) rc = fsl_b_appendf(out, "%s.%.*s", zSchema,
                                         (int)nName, zName);
          z = zCopied = zName + nName;
          continue;
        }
      }
      z += 6;
      continue;
    }
    ++z;
  }
  if( 0==rc ) rc = fsl_b_append(out, zCopied, (fsl_int_t)(z - zCopied));
  return rc;
}

/**
   The SQL functions which the scratch connection of
   fsl__ticket_schema_install_prefixed() may run: SQLite's own core,
   aggregate, window, date and time, JSON and math functions, sorted
   for bsearch(). Every other function is denied, since a connection
   gets those of every sqlite3_auto_extension() of the process, e.g.
   fsl_sqlext_init()'s fsl_open() or fsl_sync(), or an app's file
   functions, which a ticket schema (repository data, which config sync
   can bring in) must not reach. The sqlite_drop_column() and
   sqlite_rename_*() ones are SQLite's internal ones behind ALTER
   TABLE, which SQL cannot call. Not here: the full-text search
   functions, as virtual tables are refused anyway, and sqlite_log().
   A function of the process's own which takes one of these names
   (e.g. by an auto-extension) passes, as it would in file mode.
*/
static char const * const fsl__tkt_scratch_funcs[] = {
  "->", "->>", "abs", "acos", "acosh", "asin", "asinh", "atan", "atan2",
  "atanh", "avg", "ceil", "ceiling", "changes", "char", "coalesce",
  "concat", "concat_ws", "cos", "cosh", "count", "cume_dist",
  "current_date", "current_time", "current_timestamp", "date",
  "datetime", "degrees", "dense_rank", "exp", "first_value", "floor",
  "format", "glob", "group_concat", "hex", "if", "ifnull", "iif",
  "instr", "json", "json_array", "json_array_insert",
  "json_array_length", "json_error_position", "json_extract",
  "json_group_array", "json_group_object", "json_insert",
  "json_object", "json_patch", "json_pretty", "json_quote",
  "json_remove", "json_replace", "json_set", "json_type", "json_valid",
  "jsonb", "jsonb_array", "jsonb_array_insert", "jsonb_extract",
  "jsonb_group_array", "jsonb_group_object", "jsonb_insert",
  "jsonb_object", "jsonb_patch", "jsonb_remove", "jsonb_replace",
  "jsonb_set", "julianday", "lag", "last_insert_rowid", "last_value",
  "lead", "length", "like", "likelihood", "likely", "ln", "log",
  "log10", "log2", "lower", "ltrim", "max", "min", "mod", "nth_value",
  "ntile", "nullif", "octet_length", "percent_rank", "pi", "pow",
  "power", "printf", "quote", "radians", "random", "randomblob",
  "rank", "replace", "round", "row_number", "rtrim", "sign", "sin",
  "sinh", "sqlite_compileoption_get", "sqlite_compileoption_used",
  "sqlite_drop_column", "sqlite_rename_column", "sqlite_rename_quotefix",
  "sqlite_rename_table", "sqlite_rename_test",
  "sqlite_source_id", "sqlite_version", "sqrt", "strftime",
  "string_agg", "substr", "substring", "subtype", "sum", "tan", "tanh",
  "time", "timediff", "total", "total_changes", "trim", "trunc",
  "typeof", "unhex", "unicode", "unistr", "unistr_quote", "unixepoch",
  "unlikely", "upper", "zeroblob"
};

/** bsearch() comparison for fsl__tkt_scratch_funcs. */
static int fsl__tkt_scratch_func_cmp(void const * pKey, void const * pElem){
  return fsl_stricmp((char const *)pKey, *(char const * const *)pElem);
}

/** State of fsl__tkt_scratch_auth(): what it denied, if anything. */
typedef struct {
  bool denied;
  char zWhat[64];
} fsl__tkt_scratch_state;

/**
   sqlite3_set_authorizer() callback for the scratch connection of
   fsl__ticket_schema_install_prefixed(), which allows only what makes
   and fills tables, indexes, views and triggers of its own in-memory
   db (and what libfossil then does there: ALTER TABLE RENAME, DROP
   TABLE), and of SQL functions only SQLite's own
   (fsl__tkt_scratch_funcs). So it denies ATTACH and DETACH (also
   stopped by SQLITE_LIMIT_ATTACHED=0, as is VACUUM INTO, which
   ATTACHes), PRAGMA, TEMP objects and virtual tables. The in-tree
   SQLite has no load_extension() (SQLITE_OMIT_LOAD_EXTENSION). It
   records what it denied in pState, a fsl__tkt_scratch_state.
*/
static int fsl__tkt_scratch_auth(void * pState, int op, char const * z1,
                                 char const * z2, char const * z3,
                                 char const * z4){
  fsl__tkt_scratch_state * const st = pState;
  (void)z1; (void)z3; (void)z4;
  switch(op){
    case SQLITE_CREATE_INDEX: case SQLITE_CREATE_TABLE:
    case SQLITE_CREATE_TRIGGER: case SQLITE_CREATE_VIEW:
    case SQLITE_DROP_INDEX: case SQLITE_DROP_TABLE:
    case SQLITE_DROP_TRIGGER: case SQLITE_DROP_VIEW:
    case SQLITE_INSERT: case SQLITE_UPDATE: case SQLITE_DELETE:
    case SQLITE_READ: case SQLITE_SELECT: case SQLITE_RECURSIVE:
    case SQLITE_ALTER_TABLE: case SQLITE_TRANSACTION: case SQLITE_SAVEPOINT:
    case SQLITE_REINDEX /* which CREATE INDEX asks for */:
      return SQLITE_OK;
    case SQLITE_FUNCTION:
      if(z2 && bsearch(z2, fsl__tkt_scratch_funcs,
                       sizeof(fsl__tkt_scratch_funcs)
                       / sizeof(fsl__tkt_scratch_funcs[0]),
                       sizeof(fsl__tkt_scratch_funcs[0]),
                       fsl__tkt_scratch_func_cmp)){
        return SQLITE_OK;
      }
      break;
    default:
      break;
  }
  if(!st->denied){
    st->denied = true;
    fsl_snprintf(st->zWhat, sizeof(st->zWhat), "%s",
                 SQLITE_FUNCTION==op && z2 ? z2
                 : SQLITE_PRAGMA==op ? "PRAGMA"
                 : SQLITE_ATTACH==op ? "ATTACH"
                 : SQLITE_DETACH==op ? "DETACH" : "that statement");
  }
  return SQLITE_DENY;
}

/**
   fsl__ticket_schema_install() for repository tables of a host's main
   db with prefix zPre: zSql runs, as data, in a scratch in-memory
   connection of its own, where it can touch nothing else, beside empty
   stand-ins for the repository's other tables. Each object it makes is
   then made in f's repository, renamed, tables first. SQLite's ALTER
   TABLE RENAME renames the tables wherever they are named: renaming
   the stand-ins gives REFERENCES clauses the prefix, and renaming
   zSql's tables once the stand-ins are dropped fails if a trigger or
   view names a table which zSql did not make, which in f's db would be
   a table of the repository's or the host's. A schema which makes
   anything else (a TEMP object, a virtual table, whose module
   arguments name tables which no rename follows, a trigger on a table
   it did not make), or fails there, e.g. as it tries to reach beyond
   that connection (fsl__tkt_scratch_auth()), is refused too, with
   FSL_RC_CONSISTENCY.
*/
static int fsl__ticket_schema_install_prefixed(fsl_cx * const f,
                                               char const * zPre,
                                               char const * zSql){
  fsl_db * const db = fsl_cx_db_repo(f);
  fsl_db s = fsl_db_empty;
  sqlite3 * dbh = NULL;
  fsl__tkt_scratch_state auth = {false, {0}};
  char * zDenied = NULL;
  fsl_b * const sql = fsl__cx_scratchpad(f);
  fsl_b * const ren = fsl__cx_scratchpad(f);
  fsl_b * const drop = fsl__cx_scratchpad(f);
  fsl_stmt q = fsl_stmt_empty;
  char const * zWhy = NULL;
  int rc = fsl_cx_prepare(f, &q, "SELECT substr(name, %d) FROM"
                          " main.sqlite_schema WHERE type='table'"
                          " AND name GLOB '%q*'",
                          (int)fsl_strlen(zPre) + 1, zPre);
  while( fsl__cx_stmt_step_each(f, &q, &rc) ){
    char const * const z = fsl_stmt_g_text(&q, 0, NULL);
    rc = fsl_b_appendf(sql, "CREATE TABLE main.%!Q(x);\n", z);
    if(!rc) rc = fsl_b_appendf(ren, "ALTER TABLE main.%!Q RENAME TO"
                               " \"%s%s\";\n", z, zPre, z);
    if(!rc) rc = fsl_b_appendf(drop, "DROP TABLE main.\"%s%s\";\n",
                               zPre, z);
  }
  fsl_stmt_finalize(&q);
  if(!rc){
    /* An in-memory db which can reach nothing else, before any of zSql
       runs: SQLite does not allow ATTACH in a transaction, but this
       connection is in autocommit mode. */
    rc = sqlite3_open_v2(":memory:", &dbh, SQLITE_OPEN_READWRITE
                         | SQLITE_OPEN_CREATE | SQLITE_OPEN_MEMORY, NULL);
    if(rc){
      rc = fsl_cx_err_set(f, FSL_RC_DB, "Cannot open a scratch db: %s",
                          dbh ? sqlite3_errmsg(dbh) : "out of memory");
    }else{
      sqlite3_limit(dbh, SQLITE_LIMIT_ATTACHED, 0);
      sqlite3_set_authorizer(dbh, fsl__tkt_scratch_auth, &auth);
      fsl__db_borrow(&s, dbh);
    }
  }
  if(!rc && sql->used) rc = fsl_db_exec_multi(&s, "%b", sql);
  if(!rc){
    /* Its CREATE names, whatever their schema, go to s's main db. */
    fsl_b_reuse(sql);
    s.impl.share.zRepo = fsl_strdup("main");
    rc = s.impl.share.zRepo
      ? fsl__ticket_schema_qualify(&s, zSql, sql) : FSL_RC_OOM;
  }
  if(!rc && fsl_db_exec_multi(&s, "%b", sql)){
    if(auth.denied){
      zWhy = zDenied = fsl_mprintf("it reaches beyond a db of its own, "
                                   "which SQLite's authorizer denied: %s "
                                   "(only SQLite's own functions, and no "
                                   "ATTACH, DETACH, PRAGMA, TEMP object "
                                   "or virtual table)", auth.zWhat);
      if(!zDenied) rc = FSL_RC_OOM;
    }else{
      zWhy = fsl_b_cstr(&s.error.msg);
    }
  }
  if(!rc && !zWhy){
    if(fsl_db_exists(&s, "SELECT 1 FROM temp.sqlite_schema")
       || fsl_db_exists(&s, "SELECT 1 FROM main.sqlite_schema"
                        " WHERE sql LIKE 'CREATE VIRTUAL %%'")){
      zWhy = "it makes a TEMP object or a virtual table";
    }
  }
  if(!rc && !zWhy){
    /* CREATE TRIGGER resolves no functions, and the renames compile
       the triggers without the authorizer, so compile them here, by
       preparing (not running) each statement which fires them, so
       that an unknown function, or one not of fsl__tkt_scratch_funcs,
       is refused. On a view, which only INSTEAD OF triggers make
       writable, those it has none for cannot be prepared, which is
       fine. */
    fsl_stmt t = fsl_stmt_empty;
    fsl_b * const set = fsl__cx_scratchpad(f);
    rc = fsl_db_prepare(&s, &q, "SELECT DISTINCT t.tbl_name, o.type"
                        " FROM main.sqlite_schema t JOIN main.sqlite_schema o"
                        " ON o.name=t.tbl_name WHERE t.type='trigger'");
    while(!rc && !zWhy && FSL_RC_STEP_ROW==fsl_stmt_step(&q)){
      char const * const zTab = fsl_stmt_g_text(&q, 0, NULL);
      bool const isView = 'v'==*fsl_stmt_g_text(&q, 1, NULL);
      fsl_b_reuse(set);
      rc = fsl_db_prepare(&s, &t, "SELECT * FROM main.%!Q", zTab);
      for(int i = 0; !rc && i < fsl_stmt_col_count(&t); ++i){
        rc = fsl_b_appendf(set, "%s%!Q=%!Q", i ? "," : "",
                           fsl_stmt_col_name(&t, i),
                           fsl_stmt_col_name(&t, i));
      }
      fsl_stmt_finalize(&t);
      for(int i = 0; !rc && !zWhy && i < 3; ++i){
        int const prc = 0==i
          ? fsl_db_prepare(&s, &t, "INSERT INTO main.%!Q DEFAULT VALUES",
                           zTab)
          : (1==i ? fsl_db_prepare(&s, &t, "UPDATE main.%!Q SET %b",
                                   zTab, set)
             : fsl_db_prepare(&s, &t, "DELETE FROM main.%!Q", zTab));
        fsl_stmt_finalize(&t);
        if(prc && !(isView && !auth.denied
                    && strstr(fsl_b_cstr(&s.error.msg),
                              "because it is a view"))){
          zWhy = fsl_b_cstr(&s.error.msg);
        }
        if(!zWhy) fsl_db_err_reset(&s);
      }
    }
    fsl_stmt_finalize(&q);
    fsl__cx_scratchpad_yield(f, set);
    if(!rc && auth.denied){
      zWhy = zDenied = fsl_mprintf("its trigger reaches beyond a db of "
                                   "its own, which SQLite's authorizer "
                                   "denied: %s (only SQLite's own "
                                   "functions)", auth.zWhat);
      if(!zDenied) rc = FSL_RC_OOM;
    }
  }
  if(!rc && !zWhy && ren->used && fsl_db_exec_multi(&s, "%b", ren)){
    zWhy = fsl_b_cstr(&s.error.msg);
  }
  if(!rc && !zWhy && fsl_db_exists(&s, "SELECT 1 FROM main.sqlite_schema"
                                   " WHERE type='trigger'"
                                   " AND tbl_name GLOB '%q*'", zPre)){
    zWhy = "it makes a trigger on a table which it does not make";
  }
  if(!rc && !zWhy && drop->used) rc = fsl_db_exec_multi(&s, "%b", drop);
  if(!rc && !zWhy){
    fsl_b_reuse(ren);
    rc = fsl_db_prepare(&s, &q, "SELECT name FROM main.sqlite_schema"
                        " WHERE type='table' AND name NOT GLOB 'sqlite_*'");
    while(!rc && FSL_RC_STEP_ROW==fsl_stmt_step(&q)){
      char const * const z = fsl_stmt_g_text(&q, 0, NULL);
      rc = fsl_b_appendf(ren, "ALTER TABLE main.%!Q RENAME TO \"%s%s\";\n",
                         z, zPre, z);
    }
    fsl_stmt_finalize(&q);
    if(!rc && ren->used && fsl_db_exec_multi(&s, "%b", ren)){
      zWhy = fsl_b_cstr(&s.error.msg);
    }
  }
  if(!rc && !zWhy){
    /* A view whose tables zSql did not make: the renames check views
       only if there was a table to rename. */
    rc = fsl_db_prepare(&s, &q, "SELECT name FROM main.sqlite_schema"
                        " WHERE type='view'");
    while(!rc && !zWhy && FSL_RC_STEP_ROW==fsl_stmt_step(&q)){
      fsl_stmt v = fsl_stmt_empty;
      if(fsl_db_prepare(&s, &v, "SELECT 1 FROM main.%!Q",
                        fsl_stmt_g_text(&q, 0, NULL))){
        zWhy = fsl_b_cstr(&s.error.msg);
      }
      fsl_stmt_finalize(&v);
    }
    fsl_stmt_finalize(&q);
  }
  if(!rc && !zWhy){
    fsl_b_reuse(sql);
    rc = fsl_db_prepare(&s, &q,
      "SELECT sql, CASE WHEN type='table' THEN name ELSE %Q||name END"
      " FROM main.sqlite_schema WHERE sql IS NOT NULL"
      " AND name NOT GLOB 'sqlite_*' ORDER BY type<>'table', rowid", zPre);
    while(!rc && FSL_RC_STEP_ROW==fsl_stmt_step(&q)){
      rc = fsl__repo_copy_sql(sql, fsl_stmt_g_text(&q, 0, NULL),
                              fsl__db_schema(db, FSL_DBROLE_REPO),
                              fsl_stmt_g_text(&q, 1, NULL));
      if(!rc) rc = fsl_b_append(sql, ";\n", 2);
    }
    fsl_stmt_finalize(&q);
    if(!rc) rc = fsl_cx_exec_multi(f, "%b", sql);
  }
  if(zWhy){
    rc = fsl_cx_err_set(f, FSL_RC_CONSISTENCY, "Refusing the ticket "
                        "schema for the repository tables prefixed %s: "
                        "%s.", zPre, zWhy);
  }else if(rc && !f->error.code){
    rc = s.error.code
      ? fsl_cx_err_set(f, rc, "Ticket schema error: %b", &s.error.msg)
      : fsl_cx_err_set(f, rc, NULL);
  }
  fsl_free(zDenied);
  fsl_db_close(&s)/*does not close the borrowed dbh*/;
  sqlite3_close(dbh);
  fsl__cx_scratchpad_yield(f, sql);
  fsl__cx_scratchpad_yield(f, ren);
  fsl__cx_scratchpad_yield(f, drop);
  return rc;
}

int fsl__ticket_schema_install(fsl_cx * const f, char const * zSql){
  fsl_db * const db = fsl_cx_db_repo(f);
  char const * const zPre = fsl__db_repo_prefix(db);
  int rc;
  if(zPre) return fsl__ticket_schema_install_prefixed(f, zPre, zSql);
  else{
    fsl_b * const q = fsl__cx_scratchpad(f);
    rc = fsl__ticket_schema_qualify(db, zSql, q);
    if(!rc) rc = fsl_cx_exec_multi(f, "%b", q);
    fsl__cx_scratchpad_yield(f, q);
  }
  return rc;
}

int fsl__cx_ticket_create_table(fsl_cx * const f){
  fsl_db * const db = fsl_needs_repo(f);
  int rc;
  if(!db) return FSL_RC_NOT_A_REPO;
  rc = fsl_cx_exec_multi(f,
                         "DROP TABLE IF EXISTS {{dbname.repo}}.ticket;"
                         "DROP TABLE IF EXISTS {{dbname.repo}}.ticketchng;"
                         );
  if(!rc){
    /* The schema is data (possibly a repository's own, in fossil(1)'s
       form), so its placeholders are not expanded: its object names
       are given db's repository schema instead. */
    fsl_b * const buf = fsl__cx_content_buffer(f);
    rc = fsl_cx_schema_ticket(f, buf);
    if(!rc) rc = fsl__ticket_schema_install(f, fsl_b_cstr(buf));
    fsl__cx_content_buffer_yield(f);
  }
  return rc;
}

static int fsl__tkt_field_id(fsl_list const * jli, const char *zFieldName){
  int i;
  fsl_card_J const * jc;
  for(i=0; i<(int)jli->used; ++i){
    jc = (fsl_card_J const *)jli->list[i];
    if( !fsl_strcmp(zFieldName, jc->field) ) return i;
  }
  return -1;
}

int fsl__cx_ticket_load_fields(fsl_cx * const f, bool forceReload){
  fsl_list * const li = &f->ticket.customFields;
  if(li->used){
    if(!forceReload) return 0;
    fsl__card_J_list_free(li, false);
    /* Fall through and reload ... */
  }else if( !fsl_needs_repo(f) ){
    return FSL_RC_NOT_A_REPO;
  }
  fsl_card_J * jc;
  fsl_stmt q = fsl_stmt_empty;
  int i;
  fsl_b * const tbl = fsl__cx_scratchpad(f);
  /* PRAGMA's table name is a value: a prefixed table's name is bare. */
  int rc = fsl__db_table_name(fsl_cx_db_repo(f), FSL_DBROLE_REPO, "ticket",
                              false, tbl);
  if(!rc) rc = fsl_cx_prepare(f, &q, "PRAGMA %s.table_info(%b)",
                              fsl__db_schema(f->dbMain, FSL_DBROLE_REPO),
                              tbl);
  if(!rc) while( fsl__cx_stmt_step_each(f, &q, &rc) ){
    char const * zFieldName = fsl_stmt_g_text(&q, 1, NULL);
    if(!zFieldName){
      rc = FSL_RC_OOM;
      break;
    }
    f->ticket.hasTicket = 1;
    if( 0==memcmp(zFieldName,"tkt_", 4)){
      if( 0==fsl_strcmp(zFieldName,"tkt_ctime")) f->ticket.hasCTime = 1;
      /* These are core field names, part of every fossil ticket
         table. */
      continue;
    }
    jc = fsl_card_J_malloc(0, zFieldName, NULL);
    if(!jc){
      rc = FSL_RC_OOM;
      break;
    }
    jc->flags = FSL_CARD_J_TICKET;
    rc = fsl_list_append(li, jc);
    if(rc){
      fsl_card_J_free(jc);
      break;
    }
  }
  fsl_stmt_finalize(&q);
  if(rc) goto end;

  fsl_b_reuse(tbl);
  rc = fsl__db_table_name(fsl_cx_db_repo(f), FSL_DBROLE_REPO, "ticketchng",
                          false, tbl);
  if(!rc) rc = fsl_cx_prepare(f, &q, "PRAGMA %s.table_info(%b)",
                              fsl__db_schema(f->dbMain, FSL_DBROLE_REPO),
                              tbl);
  if(!rc) while( fsl__cx_stmt_step_each(f, &q, &rc) ){
    char const * zFieldName = fsl_stmt_g_text(&q, 1, NULL);
    if(!zFieldName){
      rc = FSL_RC_OOM;
      break;
    }
    f->ticket.hasChng = 1;
    if( 0==memcmp(zFieldName,"tkt_", 4)){
      if( 0==fsl_strcmp(zFieldName,"tkt_rid")) f->ticket.hasChngRid = 1;
      /* These are core field names, part of every fossil ticketchng
         table. */
      continue;
    }
    if( (i=fsl__tkt_field_id(li, zFieldName)) >= 0){
      jc = (fsl_card_J*)li->list[i];
      jc->flags |= FSL_CARD_J_CHNG;
      continue;
    }
    jc = fsl_card_J_malloc(0, zFieldName, NULL);
    if(!jc){
      rc = FSL_RC_OOM;
      break;
    }
    jc->flags = FSL_CARD_J_CHNG;
    rc = fsl_list_append(li, jc);
    if(rc){
      fsl_card_J_free(jc);
      break;
    }
  }
  fsl_stmt_finalize(&q);
  end:
  fsl__cx_scratchpad_yield(f, tbl);
  if(!rc){
    fsl_list_sort(li, fsl__qsort_cmp_J_cards);
  }
  return rc;
}

static int fsl__ticket_insert(fsl_deck * const d, fsl_id_t tktId,
                              fsl_id_t * const tgtId){
  /* Derived from fossil(1) tkt.c:ticket_insert() */;
  fsl_cx * const f = d->f;
  fsl_id_t const rid = d->rid;
  int rc = 0;
  fsl_b * const sql1 = fsl__cx_scratchpad(f);
  fsl_b * const sql2 = fsl__cx_scratchpad(f);
  fsl_b * const sql3 = fsl__cx_scratchpad(f);
  fsl_db * const db = fsl_cx_db_repo(f);
  fsl_list const * const cf = &f->ticket.customFields;
  fsl_size_t i;
  //char const * zMimetype = NULL;
  fsl_stmt q = fsl_stmt_empty;
  char aUsed[cf->used];
  assert(rid>0 && f!=NULL && db);
  if(0==tktId){
    rc = fsl_cx_exec_multi(f, "INSERT INTO {{dbname.repo}}.ticket(tkt_uuid, tkt_mtime) "
                           "VALUES(%Q, 0)", d->K);
    if(rc) goto end;
    tktId = fsl_db_last_insert_id(db);
  }
  rc = fsl__db_appendf(db, sql1,
                       "UPDATE OR REPLACE {{dbname.repo}}.ticket"
                       " SET tkt_mtime=?1");
  if(0==rc && f->ticket.hasCTime){
    rc = fsl_b_append(sql1, ", tkt_ctime=coalesce(tkt_ctime,?1)", -1);
  }
  if(rc) goto end;
  memset(aUsed, 0, cf->used);
  for(i = 0; 0==rc && i < d->J.used; ++i){
    fsl_card_J const * const dJC = (fsl_card_J*)d->J.list[i];
    int const j = fsl__tkt_field_id(cf, dJC->field);
    if(j<0){
      /* Ticket has a field which this repo does not have. Skip it. */
      continue;
    }
    aUsed[j] = FSL_CARD_J_TICKET;
    fsl_card_J const * const rJC = (fsl_card_J*)cf->list[j];
    if(rJC->flags & FSL_CARD_J_TICKET){
      if(dJC->append){
        rc = fsl_b_appendf(sql1, ", %!Q=coalesce(%!Q,'') || %Q",
                                dJC->field, dJC->field, dJC->value);
      }else{
        rc = fsl_b_appendf(sql1, ", %!Q=%Q",
                                dJC->field, dJC->value);
      }
      if(rc) break;
    }
    if(rJC->flags & FSL_CARD_J_CHNG){
      rc = fsl_b_appendf(sql2, ",%!Q", dJC->field);
      if(0==rc) rc = fsl_b_appendf(sql3, ",%Q", dJC->value);
      if(rc) break;
    }
#if 0
    if(0==fsl_strcmp(dJC->field, "mimetype")){
      zMimetype = dJC->value;
    }
#endif
  }
  if(rc) goto end;
  /* MISSING: a block from fossil(1) tkt.c which extracts backlinks:

  if( rid>0 ){
    for(i=0; i<p->nField; i++){
      const char *zName = p->aField[i].zName;
      const char *zBaseName = zName[0]=='+' ? zName+1 : zName;
      j = fieldId(zBaseName);
      if( j<0 ) continue;
      backlink_extract(p->aField[i].zValue, zMimetype, rid, BKLNK_TICKET,
                       p->rDate, i==0);
    }
  }

  That's not critical for core ticket functionality.
  */
  rc = fsl_b_appendf(sql1, " WHERE tkt_id=%" FSL_ID_T_PFMT, tktId);
  if(rc) goto end;
  rc = fsl_cx_prepare(f, &q, "%b", sql1);
  if(rc) goto end;
  rc = fsl_stmt_bind_step(&q, "f", d->D);
  fsl_stmt_finalize(&q);
  if(rc) goto end;
  fsl_b_reuse(sql1);
  if(f->ticket.hasChngRid || sql2->used){
    bool fromTkt = false;
    if(f->ticket.hasChngRid){
      rc = fsl_b_append(sql2, ",tkt_rid", -1);
      if(0==rc) rc = fsl_b_appendf(sql3, ",%" FSL_ID_T_PFMT, d->rid);
      if(rc) goto end;
    }
    for(i = 0; 0==rc &&  i < cf->used; ++i){
      fsl_card_J const * const rJC = (fsl_card_J*)cf->list[i];
      if(0==aUsed[i] && (rJC->flags & FSL_CARD_J_BOTH)==FSL_CARD_J_BOTH){
        fromTkt = true;
        rc = fsl_b_appendf(sql2, ",%!Q", rJC->field);
        if(0==rc) rc = fsl_b_appendf(sql3, ",%!Q", rJC->field);
      }
    }
    if(rc) goto end;
    if(fromTkt){
      rc = fsl_cx_prepare(f, &q, "INSERT INTO {{dbname.repo}}.ticketchng(tkt_id,tkt_mtime%b)"
                          "SELECT %"FSL_ID_T_PFMT",?1%b "
                          "FROM {{dbname.repo}}.ticket WHERE tkt_id=%"FSL_ID_T_PFMT,
                          sql2, tktId, sql3, tktId);
    }else{
      rc = fsl_cx_prepare(f, &q, "INSERT INTO {{dbname.repo}}.ticketchng(tkt_id,tkt_mtime%b)"
                          "VALUES(%"FSL_ID_T_PFMT",?1%b)",
                          sql2, tktId, sql3);
    }
    if(0==rc) rc = fsl_stmt_bind_step(&q, "f", d->D);
  }
  end:
  fsl_stmt_finalize(&q);
  fsl__cx_scratchpad_yield(f, sql1);
  fsl__cx_scratchpad_yield(f, sql2);
  fsl__cx_scratchpad_yield(f, sql3);
  *tgtId = tktId;
  if(rc){
    /* fsl_stmt_bind_step() leaves its error in db's error state. */
    rc = fsl_cx_uplift_db_error2(f, db, rc);
  }
  return rc;
}

static int fsl__ticket_timeline_entry(fsl_deck * const d, bool isNew, fsl_id_t tagId){
  /* Derived from fossil(1) manifest.c:mainfest_ticket_event() */;
  int rc;
  fsl_b * const comment = fsl__cx_scratchpad(d->f);
  fsl_b * const brief = fsl__cx_scratchpad(d->f);
  char * zTitle = 0;
  char * zNewStatus = 0;
  fsl_db * const db = fsl_cx_db_repo(d->f);
  fsl_cx * const f = d->f;
  if(!f->ticket.titleColumn){
    assert(!f->ticket.statusColumn);
    rc = fsl_db_get_text(db, &f->ticket.titleColumn, NULL,
             "SELECT coalesce("
             "(SELECT value FROM {{dbname.repo}}.config WHERE name='ticket-title-expr'),"
             "'title')");
    if(0==rc){
      rc = fsl_db_get_text(db, &f->ticket.statusColumn, NULL,
               "SELECT coalesce("
               "(SELECT value FROM {{dbname.repo}}.config WHERE name='ticket-status-column'),"
               "'status')");
    }
    if(rc){
      rc = fsl_cx_uplift_db_error( f, db );
      goto end;
    }
  }
  rc = fsl_db_get_text(db, &zTitle, NULL,
                       "SELECT coalesce(%!Q,'unknown') "
                       "FROM {{dbname.repo}}.ticket WHERE tkt_uuid=%Q",
                       f->ticket.titleColumn, d->K);
  if(rc){
    fsl_cx_uplift_db_error(d->f, db);
    goto end;
  }
  if(isNew){
    rc = fsl_b_appendf(comment, "New ticket [%!S|%S] <i>%h</i>.",
                            d->K, d->K, zTitle);
    if(0==rc){
      rc = fsl_b_appendf(brief, "New ticket [%!S|%S].",
                              d->K, d->K);
    }
    if(rc) goto end;
  }else{
    // Update an existing ticket...
    char * zNewStatus = 0;
    for(fsl_size_t i = 0; i < d->J.used; ++i){
      fsl_card_J const * const jc = (fsl_card_J*)d->J.list[i];
      if(0==fsl_strcmp(jc->field, f->ticket.statusColumn)){
        zNewStatus = jc->value;
        break;
      }
    }
    if(zNewStatus){
      rc = fsl_b_appendf(comment, "%h ticket [%!S|%S]: <i>%h</i>",
                              zNewStatus, d->K, d->K, zTitle);
      if(!rc && d->J.used>1){
        rc = fsl_b_appendf(comment, " plus %d other change%s",
                                (int)d->J.used-1, d->J.used==2 ? "" : "s");
      }
      if(0==rc) rc = fsl_b_appendf(brief, "%h ticket [%!S|%S].",
                                        zNewStatus, d->K, d->K);
      if(rc) goto end;
    }else{
      rc = fsl_db_get_text(db, &zNewStatus, NULL,
                           "SELECT coalesce(%!Q,'unknown') "
                           "FROM {{dbname.repo}}.ticket WHERE tkt_uuid=%Q",
                           f->ticket.statusColumn, d->K);
      if(rc){
        rc = fsl_cx_uplift_db_error2(f, db, rc);
        goto end;
      }
      rc = fsl_b_appendf(comment, "Ticket [%!S|%S] <i>%h</i> "
                              "status still %h with %d other change%s",
                              d->K, d->K, zTitle, zNewStatus, (int)d->J.used,
                              1==d->J.used ? "" : "s");
      fsl_free(zNewStatus);
      if(rc) goto end;
      rc = fsl_b_appendf(brief, "Ticket [%!S|%S]: %d change%s",
                              d->K, d->K, (int)d->J.used,
                              1==d->J.used ? "" : "s");
      if(rc) goto end;
    }
  }
  assert(0==rc);
  // MISSING: manifest_create_event_triggers()
  rc = fsl_cx_exec(d->f,
                   "REPLACE INTO {{dbname.repo}}.event"
                   "(type, tagid, mtime, objid, user, comment, brief) "
                   "VALUES('t', %"FSL_ID_T_PFMT", %"FSL_JULIAN_T_PFMT", "
                   "%"FSL_ID_T_PFMT",%Q,%B,%B)",
                   tagId, d->D, d->rid, d->U, comment, brief);
  end:
  fsl_free(zTitle);
  fsl_free(zNewStatus);
  fsl__cx_scratchpad_yield(d->f, comment);
  fsl__cx_scratchpad_yield(d->f, brief);
  return rc;
}

int fsl__ticket_rebuild(fsl_cx * const f, char const * zTktKCard){
  int rc;
  fsl_id_t tktId;
  fsl_id_t tagId;
  fsl_db * const db = fsl_needs_repo(f);
  fsl_stmt q = fsl_stmt_empty;
  if(!db) return FSL_RC_NOT_A_REPO;
  assert(!f->cache.isCrosslinking);
  rc = fsl__cx_ticket_load_fields(f, false);
  if(rc) goto end;
  else if(!f->ticket.hasTicket) return 0;
  char * const zTag = fsl_mprintf("tkt-%s", zTktKCard);
  if(!zTag){
    rc = FSL_RC_OOM;
    goto end;
  }
  tagId = fsl_tag_id(f, zTag, true);
  fsl_free(zTag);
  if(tagId<0){
    rc = f->error.code;
    assert(0!=rc);
    goto end;
  }
  tktId = fsl_db_g_id(db, 0, "SELECT tkt_id FROM {{dbname.repo}}.ticket "
                      "WHERE tkt_uuid=%Q", zTktKCard);
  if(tktId>0){
    if(f->ticket.hasChng){
      rc = fsl_cx_exec(f, "DELETE FROM {{dbname.repo}}.ticketchng "
                       "WHERE tkt_id=%" FSL_ID_T_PFMT,
                       tktId);
    }
    if(!rc) rc = fsl_cx_exec(f, "DELETE FROM {{dbname.repo}}.ticket "
                             "WHERE tkt_id=%" FSL_ID_T_PFMT,
                             tktId);
    if(rc) goto end;
  }
  tktId = 0;
  rc = fsl_cx_prepare(f, &q, "SELECT rid FROM {{dbname.repo}}.tagxref "
                      "WHERE tagid=%" FSL_ID_T_PFMT
                      " ORDER BY mtime", tagId);
  int counter = 0;
  /* Potential TODO (fossil does not do this):
     DELETE FROM EVENT WHERE tagid=${tagId} */
  while(0==rc && fsl__cx_stmt_step_each(f, &q, &rc)){
    fsl_deck deck = fsl_deck_empty;
    fsl_id_t const rid = fsl_stmt_g_id(&q, 0);
    rc = fsl_deck_load_rid(f, &deck, rid, FSL_SATYPE_TICKET);
    if(rc) goto outro;
    assert(deck.rid==rid);
    rc = fsl__ticket_insert(&deck, tktId, &tktId);
    if(0==rc){
      rc = fsl__ticket_timeline_entry(&deck, 0==counter++, tagId);
      if(0==rc) rc = fsl__call_xlink_listeners(&deck);
    }
    outro:
    fsl_deck_finalize(&deck);
  }
  end:
  fsl_stmt_finalize(&q);
  if(rc){
    rc = fsl_cx_uplift_db_error2(f, db, rc);
    if(FSL_RC_OOM!=rc && f->error.msg.used){
      /* Say which ticket failed. */
      fsl_b b = fsl_b_empty;
      if(0==fsl_b_appendf(&b, "Rebuilding ticket %s: %b",
                          zTktKCard, &f->error.msg)){
        fsl_b_swap(&b, &f->error.msg);
      }
      fsl_b_clear(&b);
    }
  }
  return rc;
}
