static bool fsl__xfer_have_igot( fsl_xfer *xf, fsl_uuid_cstr zUuid ){
  assert( zUuid );
  bool rv = false;
  if( 0==xf->rc ){
    /* "Have it" means we hold the content, i.e. a non-phantom blob row
    ** (size>=0). A phantom (size<0) is a placeholder for content we do
    ** NOT have and must still request, so it must not suppress the gimme.
    ** fossil's request_phantoms() sends a gimme for every phantom; the
    ** uuid-exists test alone would wrongly treat a phantom as held. Use
    ** the rid+size lookup and require size>=0. */
    fsl_stmt * const q = fsl__cx_stmt(xf->f, fsl__cx_stmt_e_blobRidSize);
    if( q ){
      int const rc = fsl_stmt_bind_step_v2(q, "s", zUuid);
      switch( rc ){
        case FSL_RC_STEP_ROW:
          rv = (fsl_stmt_g_int64(q, 1) >= 0);
          fsl_stmt_reset(q);
          break;
        case FSL_RC_STEP_DONE: break;
        default:
          xf->rc = fsl_cx_uplift_db_error2(xf->f, q->db, rc);
          break;
      }
      fsl__cx_stmt_yield(xf->f, q);
    }else{
      xf->rc = xf->f->error.code;
    }
  }
  return rv;
}

static void fsl__gimme_queue(fsl_xfer *xf, fsl_uuid_cstr zUuid){
  assert(zUuid);
  if( !fsl__xfer_have_igot(xf, zUuid)
      && 0==xf->rc /* have_igot() can change it */){
    fsl__xfer_appendcard(xf, fsl_xfcard_e_gimme, zUuid);
  }
}

